insert into public.questoes (id, rank, topic, origin, file_source, stem, options, answer, year, qnum, score, band, resolution, summary) values
($qq$1741178$qq$, 151, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Cont (CM Castro)/CM Castro/2021$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Dentre os Princípios Orçamentários, o estabelecido, de forma expressa, pelo caput do art. 2º da Lei N.º 4.320/1964, recepcionado e normatizado pelo § 5º do art. 165 da Constituição Federal, determina que a Lei Orçamentária Anual (LOA) de cada ente federado deverá conter todas as receitas e despesas de todos os poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público. Essa definição está relacionado ao Princípio Orçamentário da:  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                            20/54$qq$, $qq$[["A", "Universalidade."], ["B", "Totalidade."], ["C", "Orçamento bruto."], ["D", "Anualidade."], ["E", "Exclusividade."]]$qq$::jsonb, $qq$A$qq$, 2021, 66, 1102, $qq$A$qq$, $qq${"cobranca": "Princípio da universalidade", "regra": "A universalidade determina que a LOA de cada ente contenha todas as receitas e despesas dos Poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público.", "passos": ["1) O enunciado menciona expressamente “todas as receitas e despesas”.", "2) Também cita Poderes, órgãos, entidades, fundos e fundações.", "3) Essa combinação é a definição de universalidade no MCASP.", "4) Logo, a resposta é A."], "calculo": "", "correta": "A) Universalidade.", "erradas": ["B) Totalidade — orçamento único por ente.", "C) Orçamento bruto — valores totais sem deduções.", "D) Anualidade — período do orçamento.", "E) Exclusividade — proibição de matéria estranha à LOA."], "fundamento": "Lei nº 4.320/1964, art. 2º; CF, art. 165, §5º; MCASP.", "pegadinha": "A questão usa a definição quase literal do MCASP. Não deixe “Lei Orçamentária Anual” levar você automaticamente à anualidade."}$qq$::jsonb, $qq$Dentre os Princípios Orçamentários, o estabelecido, de forma expressa, pelo caput do art. 2º da Lei N.º 4.320/1964, recepcionado e normatizado pelo § 5º do art. 165 da Constituição Federal, determina que a Lei Orçamentária Anual (LOA) de cada ente federado deverá conter todas as receitas e despesas de todos os poderes, órgãos, entidades, fundos e fundações i…$qq$),
($qq$2165659$qq$, 152, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Cont (Pref C Largo)/Pref Campo Largo/2020$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os Princípios Orçamentários visam estabelecer diretrizes norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Sob esse aspecto, avalie as afirmativas apresentadas a seguir: I. O Princípio da _________________ determina que a Lei Orçamentária Anual (LOA) de cada ente federado deverá conter todas as receitas e despesas de todos os poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público. II. O Princípio da _________________ estabelece que a Lei Orçamentária Anual (LOA) não conterá dispositivo estranho à previsão da receita e à fixação da despesa. III. O Princípio da _________________determina existência de orçamento único para cada um dos entes federados – União, estados, Distrito Federal e municípios – com a finalidade de se evitarem múltiplos orçamentos paralelos dentro da mesma pessoa política. Assinale a alternativa que preenche de forma CORRETA, respectivamente, as lacunas:$qq$, $qq$[["A", "I – totalidade; II – universalidade; III – exclusividade."], ["B", "I – universalidade; II – totalidade; III – exclusividade."], ["C", "I – universalidade; II – exclusividade; III – totalidade."], ["D", "I – totalidade; II – exclusividade; III – universalidade."], ["E", "I – exclusividade; II – universalidade; III – totalidade."]]$qq$::jsonb, $qq$C$qq$, 2020, 67, 1102, $qq$A$qq$, $qq${"cobranca": "Associação entre totalidade, universalidade e exclusividade", "regra": "I = universalidade; II = exclusividade; III = totalidade.", "passos": ["1) I fala em todas as receitas e despesas → universalidade.", "2) II fala em não conter dispositivo estranho → exclusividade.", "3) III fala em orçamento único por ente → totalidade.", "4) A sequência é universalidade, exclusividade, totalidade, correspondente à alternativa C."], "calculo": "", "correta": "C) I – universalidade; II – exclusividade; III – totalidade.", "erradas": ["A) troca as três definições.", "B) coloca totalidade no item I e exclusividade no III.", "D) coloca totalidade no I e universalidade no III.", "E) troca universalidade e exclusividade."], "fundamento": "MCASP, princípios de Universalidade, Exclusividade e Unidade ou Totalidade.", "pegadinha": "É uma questão de “palavras-chave”: todas = universalidade; estranho = exclusividade; único = totalidade."}$qq$::jsonb, $qq$Os Princípios Orçamentários visam estabelecer diretrizes norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Sob esse aspecto, avalie as afirmativas apresentadas a seguir: I. O Princípio da _________________ determina que a Lei Orçamentária Anual (LOA) de …$qq$),
($qq$916303$qq$, 153, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Cont (CM 2 Vizinhos)/CM 2 Vizinhos/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os Princípios Orçamentários visam estabelecer diretrizes norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Válidos para os Poderes Executivo, Legislativo e Judiciário de todos os entes federativos – União, estados, Distrito Federal e municípios – são estabelecidos e disciplinados por normas constitucionais, infraconstitucionais e pela doutrina. Qual das alternativas todos os itens citados são princípios orçamentários?$qq$, $qq$[["A", "Exclusividade, Relevância, Legalidade, Compreensibilidade."], ["B", "Legalidade, Publicidade, Comparabilidade, Legalidade."], ["C", "Universalidade, Orçamento bruto, Exclusividade, Legalidade, Publicidade."], ["D", "Transparência, Conservadorismo, Comparabilidade, Tempestividade."], ["E", "Transparência, Exclusividade, Relevância, Conservadorismo."]]$qq$::jsonb, $qq$C$qq$, 2019, 68, 1102, $qq$A$qq$, $qq${"cobranca": "Identificação de princípios orçamentários", "regra": "A alternativa C reúne princípios reconhecidos na abordagem de princípios orçamentários do MCASP, incluindo universalidade, orçamento bruto, exclusividade, legalidade e publicidade.", "passos": ["1) Verifique cada conjunto.", "2) A alternativa C contém apenas princípios orçamentários: universalidade, orçamento bruto, exclusividade, legalidade e publicidade.", "3) As demais misturam princípios orçamentários com características/qualidades da informação contábil, como relevância, comparabilidade, compreensibilidade, conservadorismo e tempestividade.", "4) Portanto, C é a correta."], "calculo": "", "correta": "C) Universalidade, Orçamento bruto, Exclusividade, Legalidade, Publicidade.", "erradas": ["A) mistura princípios orçamentários com relevância e compreensibilidade, ligadas à informação contábil.", "B) mistura publicidade com comparabilidade e repete legalidade.", "D) reúne características qualitativas/contábeis, não a lista pedida de princípios orçamentários.", "E) mistura exclusividade com relevância e conservadorismo."], "fundamento": "MCASP, Parte I — Procedimentos Contábeis Orçamentários, seção de princípios orçamentários.", "pegadinha": "A banca mistura princípios orçamentários com características qualitativas da informação contábil. Identifique o “intruso” em cada alternativa."}$qq$::jsonb, $qq$Os Princípios Orçamentários visam estabelecer diretrizes norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Válidos para os Poderes Executivo, Legislativo e Judiciário de todos os entes federativos – União, estados, Distrito Federal e municípios – são est…$qq$),
($qq$990583$qq$, 154, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Proc (Pref Foz do Iguaçu)/Pref Foz do Iguaçu/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$A instituição orçamentária foi cercada de uma série de regras ou princípios para auxiliar o controle parlamentar sobre os Executivos. Os princípios orçamentários são premissas a serem observadas na concepção da proposta orçamentária. Sobre o tema é CORRETO afirmar que:$qq$, $qq$[["A", "A anualidade ou periodicidade é a elaboração e autorização do orçamento para um determinado período de tempo, geralmente sendo programado para o exercício financeiro seguinte, possuindo previsão constitucional."], ["B", "A lei orçamentária anual não conterá dispositivo estranho à previsão da receita e à fixação da despesa, não se incluindo na proibição a autorização para abertura de créditos suplementares e contratação de operações de crédito, com exceção no caso de antecipação de receita."], ["C", "O princípio da unidade ou totalidade garante que todos os gastos com dinheiro público estejam presentes no documento para consulta de qualquer cidadão."], ["D", "O princípio da universalidade garante que apenas um orçamento seja feito por cada ente federativo contendo todas as despesas previstas para um determinado período."], ["E", "O princípio da não vinculação de receita e imposto garante que não usem a receita de impostos para outras despesas que não sejam remuneração dos servidores públicos."]]$qq$::jsonb, $qq$A$qq$, 2019, 69, 1102, $qq$A$qq$, $qq${"cobranca": "Princípios da anualidade, exclusividade, unidade/totalidade e universalidade", "regra": "A alternativa A descreve corretamente a anualidade ou periodicidade: o orçamento é elaborado e autorizado para um período determinado, em regra o exercício financeiro, com previsão constitucional.", "passos": ["1) A alternativa A associa anualidade à elaboração e autorização do orçamento para período determinado.", "2) Isso corresponde ao princípio da anualidade/periodicidade.", "3) B está incorreta porque a exceção constitucional abrange a autorização para abertura de créditos suplementares e contratação de operações de crédito, inclusive por antecipação de receita; a redação da alternativa restringe indevidamente a exceção.", "4) C e D trocam unidade e universalidade; E apresenta incorretamente a não vinculação de impostos."], "calculo": "", "correta": "A) A anualidade ou periodicidade é a elaboração e autorização do orçamento para determinado período, normalmente o exercício financeiro.", "erradas": ["B) A redação não reproduz corretamente o alcance da exceção do art. 165, §8º.", "C) A descrição dada é de universalidade, não de unidade/totalidade.", "D) A descrição mistura unidade e universalidade.", "E) A não vinculação de impostos não significa reservar sua utilização apenas à remuneração de servidores."], "fundamento": "CF, art. 165; Lei nº 4.320/1964, arts. 2º e 34; CF, art. 165, §8º.", "pegadinha": "A questão exige distinguir “um orçamento” (unidade/totalidade), “todas as receitas e despesas” (universalidade) e “um período” (anualidade)."}$qq$::jsonb, $qq$A instituição orçamentária foi cercada de uma série de regras ou princípios para auxiliar o controle parlamentar sobre os Executivos. Os princípios orçamentários são premissas a serem observadas na concepção da proposta orçamentária. Sobre o tema é CORRETO afirmar que:$qq$),
($qq$1335919$qq$, 155, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Cont (IPREV N Esper)/IPREV N Esperança/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os Princípios Orçamentários visam estabelecer diretrizes norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. A esse respeito, o orçamento público deve ser único para cada um dos entes federados – União, estados, Distrito Federal e municípios – com a finalidade de se evitarem múltiplos orçamentos paralelos dentro da mesma pessoa política. Dessa forma, todas as receitas previstas e despesas fixadas, em cada exercício financeiro, devem integrar um único documento legal dentro de cada esfera federativa: a Lei Orçamentária Anual (LOA). Essa definição está relacionado ao Princípio Orçamentário da:$qq$, $qq$[["A", "Totalidade."], ["B", "Exclusividade."], ["C", "Anualidade."], ["D", "Transparência."], ["E", "Universalidade.  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                               21/54"]]$qq$::jsonb, $qq$A$qq$, 2019, 70, 1102, $qq$A$qq$, $qq${"cobranca": "Princípio da unidade ou totalidade", "regra": "Unidade ou totalidade determina um orçamento único para cada ente federativo, reunindo as previsões e autorizações orçamentárias no documento legal correspondente.", "passos": ["1) O enunciado usa a expressão “orçamento deve ser único para cada ente”.", "2) Essa é a definição direta de unidade ou totalidade.", "3) A questão ainda explica que as receitas previstas e despesas fixadas integram uma única LOA.", "4) Portanto, A é correta."], "calculo": "", "correta": "A) Totalidade.", "erradas": ["B) Exclusividade — limita o conteúdo da LOA.", "C) Anualidade — delimita o período.", "D) Transparência — relaciona-se à divulgação.", "E) Universalidade — exige abrangência de todas as receitas e despesas."], "fundamento": "Lei nº 4.320/1964, art. 2º; MCASP, Unidade ou Totalidade.", "pegadinha": "“Único” = unidade/totalidade; “todos” = universalidade."}$qq$::jsonb, $qq$Os Princípios Orçamentários visam estabelecer diretrizes norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. A esse respeito, o orçamento público deve ser único para cada um dos entes federados – União, estados, Distrito Federal e municípios – com a finali…$qq$),
($qq$1336829$qq$, 156, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Cont Jr (FOZTRANS)/FOZTRANS/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os princípios são orientadores de todo o processo orçamentário. Vale destacar que princípio, em qualquer contexto, representa um conjunto de normas orientadoras de todo um processo. Quanto ao orçamento público, esses princípios vão orientar o processo orçamentário, que vai desde a elaboração até o controle e avaliação. Neste contexto, assinale a opção que apresenta regra decorrente do princípio da unidade:$qq$, $qq$[["A", "As receitas e as despesas constantes na LOA serão registradas pelo valor total bruto, vedadas quaisquer deduções."], ["B", "Cada ente federado deve ter seu próprio orçamento, a fim de se evitarem múltiplos orçamentos paralelos dentro da mesma pessoa política."], ["C", "A LOA de cada ente federado deve conter as receitas e as despesas dos respectivos poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo poder público."], ["D", "O período de tempo ao qual a previsão das receitas e a fixação das despesas registradas na LOA se refiram deve coincidir com o ano civil: de 1.º de janeiro a 31 de dezembro de cada ano."], ["E", "A LOA será única e não conterá dispositivo estranho à previsão da receita e à fixação da despesa."]]$qq$::jsonb, $qq$B$qq$, 2019, 71, 1102, $qq$A$qq$, $qq${"cobranca": "Princípio da unidade", "regra": "A unidade determina que cada ente federado possua seu próprio orçamento, evitando múltiplos orçamentos paralelos dentro da mesma pessoa política.", "passos": ["1) Procure a alternativa que descreve um único orçamento para cada ente.", "2) A alternativa B traz exatamente essa regra.", "3) A é orçamento bruto; C é universalidade; D é anualidade; E mistura unidade e exclusividade.", "4) Logo, B é a resposta."], "calculo": "", "correta": "B) Cada ente federado deve ter seu próprio orçamento, evitando múltiplos orçamentos paralelos dentro da mesma pessoa política.", "erradas": ["A) Orçamento bruto.", "C) Universalidade.", "D) Anualidade.", "E) Combina conceitos de unidade e exclusividade, não sendo a definição pedida."], "fundamento": "Lei nº 4.320/1964, art. 2º; MCASP, Unidade ou Totalidade.", "pegadinha": "A expressão “seu próprio orçamento” aqui significa um orçamento único dentro de cada ente, não vários orçamentos paralelos."}$qq$::jsonb, $qq$Os princípios são orientadores de todo o processo orçamentário. Vale destacar que princípio, em qualquer contexto, representa um conjunto de normas orientadoras de todo um processo. Quanto ao orçamento público, esses princípios vão orientar o processo orçamentário, que vai desde a elaboração até o controle e avaliação. Neste contexto, assinale a opção que ap…$qq$),
($qq$1336832$qq$, 157, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Cont Jr (FOZTRANS)/FOZTRANS/2019$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os princípios orçamentários são regras que cercam a instituição orçamentária, visando a dar-lhe consistência, principalmente no que se refere ao controle pelo Poder Legislativo. Em relação aos princípios orçamentários, assinale a opção CORRETA:$qq$, $qq$[["A", "Pelo princípio da exclusividade, o orçamento deve ser uno, isto é, deve existir apenas um orçamento para o exercício financeiro, para cada ente da Federação."], ["B", "Em observância ao princípio da unidade, as despesas devem ser classificadas de forma detalhada, o que facilita sua análise e compreensão."], ["C", "O princípio da universalidade dispõe que o conteúdo orçamentário deve ser divulgado por meio dos veículos oficiais de comunicação, para conhecimento público e para a eficácia de sua validade."], ["D", "Conforme estabelece o princípio da transparência, as previsões de receita e de despesa devem fazer referência, sempre, a um período limitado de tempo."], ["E", "Segundo a Lei N.º 4.320/1964, a Lei de Orçamento conterá discriminação da receita e da despesa, atendidos os princípios de unidade, universalidade e anualidade."]]$qq$::jsonb, $qq$E$qq$, 2019, 72, 1102, $qq$A$qq$, $qq${"cobranca": "Princípios orçamentários — Lei nº 4.320/1964", "regra": "O art. 2º da Lei nº 4.320/1964 determina que a Lei do Orçamento obedeça aos princípios de unidade, universalidade e anualidade.", "passos": ["1) A questão pede a alternativa correta.", "2) A alternativa E reproduz a estrutura do art. 2º da Lei nº 4.320/1964.", "3) A, B, C e D trocam as definições dos princípios.", "4) Portanto, E é correta."], "calculo": "", "correta": "E) A Lei de Orçamento conterá discriminação da receita e da despesa, atendidos os princípios de unidade, universalidade e anualidade.", "erradas": ["A) Exclusividade não significa orçamento uno.", "B) Unidade não trata da classificação detalhada das despesas.", "C) Universalidade não é publicidade.", "D) Transparência não define a periodicidade das previsões."], "fundamento": "Lei nº 4.320/1964, art. 2º.", "pegadinha": "A questão pede uma regra legal literal. Quando aparecer “Lei nº 4.320/1964, art. 2º”, associe imediatamente unidade, universalidade e anualidade."}$qq$::jsonb, $qq$Os princípios orçamentários são regras que cercam a instituição orçamentária, visando a dar-lhe consistência, principalmente no que se refere ao controle pelo Poder Legislativo. Em relação aos princípios orçamentários, assinale a opção CORRETA:$qq$),
($qq$1054621$qq$, 158, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Cont (CM Foz do Iguaçu)/CM Foz do Iguaçu/2018$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Sobre os Princípios Orçamentários, classifique: A. Princípio da Unidade. B. Princípio da Universalidade. C. Princípio da Exclusividade. D. Princípio do Orçamento Bruto. ( ) Obriga que os registros das receitas e despesas na Lei Orçamentária Anual (LOA) sejam realizadas pelo valor total, vedadas quaisquer deduções. ( ) Estabelece que a Lei Orçamentária Anual (LOA) não conterá dispositivo estranho à previsão da receita e à fixação da despesa. ( ) Estabelece que a Lei Orçamentária Anual (LOA) de cada ente federado deverá conter todas as receitas e despesas de todos os poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público. ( ) Determina a existência de orçamento único para cada um dos entes federados, com a finalidade de se evitarem múltiplos orçamentos paralelos dentro da mesma pessoa política. Assinale a alternativa que contém, de cima para baixo, a sequência CORRETA:$qq$, $qq$[["A", "A, B, C, D."], ["B", "A, C, B, D."], ["C", "D, B, C, A."], ["D", "D, C, B, A."]]$qq$::jsonb, $qq$D$qq$, 2018, 73, 1102, $qq$A$qq$, $qq${"cobranca": "Associação dos princípios unidade, universalidade, exclusividade e orçamento bruto", "regra": "A sequência correta é: orçamento bruto = D; exclusividade = C; universalidade = B; unidade = A.", "passos": ["1) Valor total, sem deduções → orçamento bruto (D).", "2) Dispositivo estranho à receita/despesa → exclusividade (C).", "3) Todas as receitas e despesas → universalidade (B).", "4) Orçamento único por ente → unidade (A). A sequência D-C-B-A corresponde à alternativa D."], "calculo": "", "correta": "D) D, C, B, A.", "erradas": ["A) A-B-C-D — sequência incompatível com as definições.", "B) A-C-B-D — troca orçamento bruto e unidade.", "C) D-B-C-A — troca exclusividade e universalidade."], "fundamento": "Lei nº 4.320/1964, arts. 2º e 6º; CF, art. 165, §8º; MCASP.", "pegadinha": "Resolva pela palavra-chave de cada linha antes de olhar as alternativas. Isso reduz o risco de inverter universalidade e exclusividade."}$qq$::jsonb, $qq$Sobre os Princípios Orçamentários, classifique: A. Princípio da Unidade. B. Princípio da Universalidade. C. Princípio da Exclusividade. D. Princípio do Orçamento Bruto. ( ) Obriga que os registros das receitas e despesas na Lei Orçamentária Anual (LOA) sejam realizadas pelo valor total, vedadas quaisquer deduções. ( ) Estabelece que a Lei Orçamentária Anual …$qq$),
($qq$563460$qq$, 159, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Tec NS (FA)/FA/2017$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os princípios orçamentários são diretrizes de direito financeiro que se aplicam direta e imediatamente à confecção do orçamento público e são normas especificamente voltadas à elaboração do orçamento público. Com base na doutrina, na jurisprudência e nas disposições normativas, é CORRETO afirmar que:$qq$, $qq$[["A", "Com o princípio da exclusividade, positivado no artigo 165, §8º da Constituição Federal, o legislador constituinte tinha como objetivo afastar a possibilidade de as leis orçamentárias conterem previsões absolutamente estranhas ao direito financeiro, tais como temas afetos ao direito privado."], ["B", "O princípio da exclusividade do orçamento público não comporta nenhuma exceção."], ["C", "Não é necessário ou obrigatório que todas as receitas e despesas estejam previstas na Lei Orçamentária Anual, segundo o princípio da universalidade."], ["D", "O orçamento público deve conter apenas as estimativas para as receitas e despesas do próximo exercício financeiro, não devendo prever objetivos e metas relacionados à realização de necessidades públicas, segundo o princípio da programação."]]$qq$::jsonb, $qq$A$qq$, 2017, 74, 1102, $qq$A$qq$, $qq${"cobranca": "Princípio da exclusividade — art. 165, §8º, da Constituição", "regra": "A exclusividade impede que a lei orçamentária seja usada para inserir matérias absolutamente estranhas ao conteúdo orçamentário, ressalvadas as exceções constitucionais.", "passos": ["1) A alternativa A relaciona exclusividade ao art. 165, §8º.", "2) O objetivo é impedir matéria estranha à previsão da receita e à fixação da despesa.", "3) B é falsa porque o princípio possui exceções expressas.", "4) C é falsa porque universalidade exige abrangência das receitas e despesas. D é falsa porque programação não elimina objetivos e metas."], "calculo": "", "correta": "A) Com o princípio da exclusividade, positivado no art. 165, §8º, busca-se afastar a inserção de matérias absolutamente estranhas ao direito financeiro/orçamentário na lei orçamentária.", "erradas": ["B) Falsa: há exceções expressas no §8º do art. 165.", "C) Falsa: a universalidade exige a abrangência das receitas e despesas.", "D) Falsa: o orçamento não se resume a simples estimativas; a programação orçamentária envolve objetivos e ações."], "fundamento": "Constituição Federal, art. 165, §8º.", "pegadinha": "A palavra “nenhuma” em B torna a alternativa suspeita: a Constituição prevê expressamente exceções à exclusividade."}$qq$::jsonb, $qq$Os princípios orçamentários são diretrizes de direito financeiro que se aplicam direta e imediatamente à confecção do orçamento público e são normas especificamente voltadas à elaboração do orçamento público. Com base na doutrina, na jurisprudência e nas disposições normativas, é CORRETO afirmar que:$qq$),
($qq$563612$qq$, 160, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Ass Adm (FA)/FA/2017$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$A Constituição Federal estabelece que o orçamento é anual. A anuidade também aparece expressamente na Lei nº 4320/1964, que determina que a lei orçamentária obedeça ao princípio da anuidade. PORQUE É outro instrumento de controle. A periodicidade da autorização obriga os responsáveis pela execução do orçamento a manterem diálogo constante com o legislativo e com a sociedade. A respeito dessas duas afirmativas, é CORRETO afirmar que:$qq$, $qq$[["A", "Apenas a primeira afirmativa é verdadeira."], ["B", "As duas afirmativas são falsas."], ["C", "As duas afirmativas são verdadeiras e a segunda justifica a primeira."], ["D", "As duas afirmativas são verdadeiras, mas a segunda não justifica a primeira."]]$qq$::jsonb, $qq$C$qq$, 2017, 75, 1102, $qq$A$qq$, $qq${"cobranca": "Princípio da anualidade/periodicidade", "regra": "A anualidade determina que o orçamento seja aprovado para um período determinado. A periodicidade também funciona como mecanismo de controle porque a autorização orçamentária é renovada periodicamente, permitindo acompanhamento pelo Legislativo e pela sociedade.", "passos": ["1) Primeira afirmativa: a Constituição e a Lei nº 4.320/1964 adotam a anualidade/periodicidade do orçamento → verdadeira.", "2) Segunda afirmativa: a periodicidade da autorização favorece o controle e o diálogo institucional → verdadeira.", "3) A segunda explica a função de controle associada à periodicidade da autorização.", "4) Portanto, o gabarito C — ambas verdadeiras e a segunda justifica a primeira."], "calculo": "", "correta": "C) As duas afirmativas são verdadeiras e a segunda justifica a primeira.", "erradas": ["A) Falsa porque a segunda também é verdadeira.", "B) Falsa porque as duas afirmativas não são falsas.", "D) Falsa porque, no enquadramento adotado pela questão, a segunda funciona como justificativa da periodicidade."], "fundamento": "Lei nº 4.320/1964, art. 2º e art. 34; Constituição Federal, sistema orçamentário.", "pegadinha": "Em questões de “asserção e razão”, não basta as duas serem verdadeiras: é preciso verificar se a segunda explica a primeira. Aqui, o vínculo é a função de controle da periodicidade."}$qq$::jsonb, $qq$A Constituição Federal estabelece que o orçamento é anual. A anuidade também aparece expressamente na Lei nº 4320/1964, que determina que a lei orçamentária obedeça ao princípio da anuidade. PORQUE É outro instrumento de controle. A periodicidade da autorização obriga os responsáveis pela execução do orçamento a manterem diálogo constante com o legislativo e…$qq$),
($qq$563078$qq$, 161, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Proc J (CM Cambará)/CM Cambará/2016$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Analise as assertivas abaixo e assinale a alternativa INCORRETA.$qq$, $qq$[["A", "A Lei Orçamentária Anual - LOA - é a lei orçamentária mais concreta de todas, visto que dispões quase exclusivamente acerca das despesas e receitas para o exercício financeiro seguinte."], ["B", "Segundo o princípio da exclusividade, a Lei Orçamentária Anual - LOA - não conterá dispositivos estranhos à fixação de despesa e previsão de receita."], ["C", "Como única exceção do princípio da exclusividade na Lei Orçamentária Anual - LOA - está a autorização para abertura de crédito suplementar."], ["D", "O princípio da exclusividade no tocante a Lei Orçamentária Anual - LOA comporta duas exceções, dentre elas, a autorização para abertura de crédito suplementar."]]$qq$::jsonb, $qq$C$qq$, 2016, 76, 1102, $qq$A$qq$, $qq${"cobranca": "Princípio da exclusividade", "regra": "A LOA não deve conter matéria estranha à previsão da receita e à fixação da despesa. A Constituição admite duas exceções expressas: autorização para abertura de créditos suplementares e autorização para contratação de operações de crédito, inclusive por antecipação de receita, nos termos da lei.", "passos": ["1) O comando pede a alternativa INCORRETA.", "2) B descreve corretamente a regra geral da exclusividade.", "3) C afirma que existe apenas uma exceção. Isso está errado, porque há duas exceções constitucionais.", "4) D reconhece as duas exceções. Portanto, a incorreta é C."], "calculo": "Não há cálculo.", "correta": "C) É a incorreta: o princípio da exclusividade possui duas exceções, não apenas a autorização para crédito suplementar.", "erradas": ["A) Compatível com a natureza da LOA.", "B) Correta quanto à regra geral.", "D) Correta ao mencionar duas exceções."], "fundamento": "Constituição Federal, art. 165, § 8º; Lei nº 4.320/1964.", "pegadinha": "A palavra-chave é “única”. A questão tenta fazer o candidato esquecer a segunda exceção: operações de crédito.", "verificacao": "A redação da alternativa C é incompatível com o § 8º do art. 165 da CF."}$qq$::jsonb, $qq$Analise as assertivas abaixo e assinale a alternativa INCORRETA.$qq$),
($qq$563624$qq$, 162, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - AP (APPA)/APPA/Economista/2016$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Investimentos públicos em logística e infraestrutura, como a ampliação de modais ferroviários, podem contribuir para a criação de novas rotas, bem como ampliar a capacidade de movimentação de cargas até os Portos de Paranaguá e Antonina. Para realizar esses investimentos o governo precisa elaborar um orçamento público, pautado em uma série de princípios. Nesse contexto, é CORRETO afirmar que:$qq$, $qq$[["A", "O princípio orçamentário que preceitua que todas as receitas e despesas devem estar contidas em uma única lei orçamentária é o princípio do equilíbrio."], ["B", "No orçamento público, devem constar apenas conceitos e informações que se relacionem com a fixação de despesa, ou com a previsão de receita, o que é conhecido com o princípio da unidade."], ["C", "A necessidade de que todas as parcelas de receita e de despesas sejam apresentadas em seus valores brutos refere-se ao princípio da exclusividade."], ["D", "O princípio que pressupõe que o orçamento público deve conter todas as despesas e também todas as receitas da administração pública é o princípio da universalidade."]]$qq$::jsonb, $qq$D$qq$, 2016, 77, 1102, $qq$A$qq$, $qq${"cobranca": "Princípios orçamentários", "regra": "Universalidade determina que a LOA contenha todas as receitas e despesas abrangidas pelo orçamento, ressalvadas as especificidades constitucionais e legais.", "passos": ["1) A alternativa D descreve a universalidade.", "2) Equilíbrio não é o princípio que significa “todas as receitas e despesas”.", "3) Unidade/totalidade trata da existência de orçamento único por ente.", "4) Orçamento bruto exige receitas e despesas pelos seus valores totais, sem deduções."], "calculo": "Não há cálculo.", "correta": "D) Universalidade.", "erradas": ["A) Descreve universalidade, não equilíbrio.", "B) Descreve exclusividade, não unidade.", "C) Descreve orçamento bruto, não exclusividade."], "fundamento": "Lei nº 4.320/1964, arts. 2º e 3º; Constituição Federal, art. 165.", "pegadinha": "Confundir universalidade, unidade, exclusividade e orçamento bruto — quatro princípios cobrados juntos com frequência."}$qq$::jsonb, $qq$Investimentos públicos em logística e infraestrutura, como a ampliação de modais ferroviários, podem contribuir para a criação de novas rotas, bem como ampliar a capacidade de movimentação de cargas até os Portos de Paranaguá e Antonina. Para realizar esses investimentos o governo precisa elaborar um orçamento público, pautado em uma série de princípios. Nes…$qq$),
($qq$567261$qq$, 163, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Fisc Trib (Ubiratã)/Pref Ubiratã/2016$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os Princípios Orçamentários visam a estabelecer regras norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Em qual das alternativas todos os itens citados são Princípios Orçamentários?$qq$, $qq$[["A", "Unidade, Transparência, Publicidade, Legalidade, Entidade, Transparência."], ["B", "Universalidade, Unidade, Exclusividade, Transparência."], ["C", "Orçamento Bruto, Unidade, Legalidade, Competência, Exclusividade."], ["D", "Universalidade, Exclusividade, Oportunidade, Publicidade, Legalidade."]]$qq$::jsonb, $qq$B$qq$, 2016, 78, 1102, $qq$A$qq$, $qq${"cobranca": "Princípios orçamentários", "regra": "Entre os princípios orçamentários reconhecidos no MCASP estão unidade/totalidade, universalidade, anualidade/periodicidade, exclusividade, orçamento bruto, publicidade/transparência e legalidade, entre outros.", "passos": ["1) Elimine alternativas que misturam princípios orçamentários com princípios gerais da contabilidade ou conceitos de outra natureza.", "2) A alternativa B traz somente Universalidade, Unidade, Exclusividade e Transparência.", "3) Os quatro são princípios orçamentários."], "calculo": "Não há cálculo.", "correta": "B) Universalidade, Unidade, Exclusividade, Transparência.", "erradas": ["A) Entidade não é, nessa lista, princípio orçamentário.", "C) Competência é princípio contábil, não princípio orçamentário.", "D) Oportunidade não integra essa combinação de princípios orçamentários."], "fundamento": "MCASP, capítulo de princípios orçamentários; Lei nº 4.320/1964 e Constituição Federal.", "pegadinha": "A banca mistura princípios contábeis com orçamentários para induzir o candidato ao erro."}$qq$::jsonb, $qq$Os Princípios Orçamentários visam a estabelecer regras norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Em qual das alternativas todos os itens citados são Princípios Orçamentários?$qq$),
($qq$1058521$qq$, 164, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - AP (APPA)/APPA/Contador/2016$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$O quadro apresentado a seguir, especifica o Orçamento de 2016 da Administração dos Portos de Paranaguá e Antonina (APPA). Segundo a APPA, a modernização e expansão da infraestrutura portuária tem como objetivo e ações atender as novas demandas dos clientes do Porto na área de abrangência da Empresa Pública, promover o investimento nas áreas operacionais de Paranaguá e Antonina, modernizando e expandindo a infraestrutura portuária, proporcionar o aumento da capacidade instalada e elevar o desempenho operacional. Considerando que esses investimentos são realizados com recursos próprios da Empresa Pública, avalie o Orçamento de 2016, apresentado a seguir, que servirá de base para responder a questão.  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                         23/54 Fonte: Governo do Estado do Paraná. Lei nº 18.660/2015, Lei Orçamentária Anual (LOA) referente Exercício de 2016 do Estado do Paraná. Secretaria de Estado da Fazenda. Coordenação de Orçamento e Programação. Os Princípios Orçamentários visam estabelecer regras norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. Classifique os Princípios Orçamentários apresentados a seguir de acordo com sua natureza e aplicação: ( ) Previsto no § 8º do art. 165 da Constituição Federal, estabelece que a Lei Orçamentária Anual (LOA) não conterá dispositivo estranho à previsão da receita A.Unidade ou Totalidade             e à fixação da despesa. Ressalvam-se dessa proibição a autorização para abertura de crédito suplementar e a contratação de operações de crédito, nos termos da lei. ( ) Estabelecido, de forma expressa, pelo caput do art. 2º da Lei nº 4.320/ 1964, recepcionado e normatizado pelo § 5º do art. 165 da Constituição Federal, determina que a Lei Orçamentária Anual B. Universalidade. (LOA) de cada ente federado deverá conter todas as receitas e despesas de todos os poderes, órgãos, entidades, fundos e fundações instituídas e mantidas pelo Poder Público. ( ) Previsto, de forma expressa, pelo caput do art. 2º da Lei nº 4.320/1964, determina existência de orçamento único para cada um dos entes federados – União, estados, Distrito Federal e municípios – com a finalidade de se C. Anualidade ou              evitarem múltiplos orçamentos paralelos Periodicidade.               dentro da mesma pessoa política. Dessa forma, todas as receitas previstas e despesas fixadas, em cada exercício financeiro, devem integrar um único documento legal dentro de cada esfera federativa: a Lei Orçamentária Anual (LOA). D. Exclusividade.            ( ) Estipulado, de forma literal, pelo caput do art. 2º da Lei nº 4.320/1964, delimita o exercício financeiro orçamentário: período de tempo ao qual a previsão das receitas e a fixação das despesas registradas na Lei Orçamentária Anual (LOA) irão se  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                                          24/54 referir. Segundo o art. 34 da Lei nº 4.320/1964, o exercício financeiro coincidirá com o ano civil, ou seja, de 1º de janeiro a 31 de dezembro de cada ano. Após classificar os Princípios Orçamentários, assinale a alternativa que contém a sequência CORRETA.$qq$, $qq$[["A", "B, D, C, A."], ["B", "D, B, A, C."], ["C", "C, A, B, D."], ["D", "C, B, A, D."]]$qq$::jsonb, $qq$B$qq$, 2016, 79, 1102, $qq$A$qq$, $qq${"cobranca": "Classificação dos princípios orçamentários", "regra": "Exclusividade = LOA sem matéria estranha, com exceções; universalidade = todas as receitas e despesas; unidade/totalidade = orçamento único; anualidade/periodicidade = exercício financeiro delimitado.", "passos": ["1) Primeiro enunciado: exclusividade → D.", "2) Segundo: todas as receitas e despesas → universalidade → B.", "3) Terceiro: orçamento único → unidade/totalidade → A.", "4) Quarto: exercício financeiro coincidente com o ano civil → anualidade/periodicidade → C.", "5) Sequência D, B, A, C corresponde à alternativa B."], "calculo": "Não há cálculo.", "correta": "B) D, B, A, C.", "erradas": ["A) Troca a sequência inicial.", "C) Começa por anualidade, mas o primeiro conceito é exclusividade.", "D) Coloca universalidade na terceira descrição, que é unidade."], "fundamento": "Constituição Federal, art. 165, § 8º; Lei nº 4.320/1964, arts. 2º e 34.", "pegadinha": "A questão exige reconhecer o conceito antes de olhar as letras. Memorizar apenas a sequência pode levar a erro quando a ordem muda."}$qq$::jsonb, $qq$O quadro apresentado a seguir, especifica o Orçamento de 2016 da Administração dos Portos de Paranaguá e Antonina (APPA). Segundo a APPA, a modernização e expansão da infraestrutura portuária tem como objetivo e ações atender as novas demandas dos clientes do Porto na área de abrangência da Empresa Pública, promover o investimento nas áreas operacionais de P…$qq$),
($qq$3013725$qq$, 165, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - Tes (CM Nova Londrina)/CM Nova Londrina/2016$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Os Princípios Orçamentários visam estabelecer regras norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. O Princípio da atividade da Administração Pública no regime democrático está previsto no caput do art. 37 da Constituição Federal, justifica-se especialmente pelo fato de o orçamento ser fixado em lei, sendo esta a que autoriza aos Poderes a execução de suas despesas.$qq$, $qq$[["A", "Universalidade."], ["B", "Exclusividade."], ["C", "Legalidade."], ["D", "Publicidade."]]$qq$::jsonb, $qq$D$qq$, 2016, 80, 1102, $qq$A$qq$, $qq${"cobranca": "Princípio da publicidade", "regra": "A publicidade é princípio constitucional da Administração Pública e exige divulgação dos atos administrativos, permitindo transparência e controle social.", "passos": ["1) O enunciado relaciona o regime democrático à divulgação pública.", "2) O art. 37, caput, da CF inclui a publicidade entre os princípios da Administração Pública.", "3) Portanto, a alternativa correspondente é Publicidade."], "calculo": "Não há cálculo.", "correta": "D) Publicidade.", "erradas": ["A) Universalidade trata da abrangência das receitas e despesas.", "B) Exclusividade trata do conteúdo permitido na LOA.", "C) Legalidade trata da atuação conforme a lei."], "fundamento": "Constituição Federal, art. 37, caput.", "pegadinha": "A banca usa o contexto orçamentário, mas a pista decisiva está em “divulgação pública”."}$qq$::jsonb, $qq$Os Princípios Orçamentários visam estabelecer regras norteadoras básicas, a fim de conferir racionalidade, eficiência e transparência para os processos de elaboração, execução e controle do orçamento público. O Princípio da atividade da Administração Pública no regime democrático está previsto no caput do art. 37 da Constituição Federal, justifica-se especia…$qq$),
($qq$923513$qq$, 166, $qq$AFO, Direito Financeiro e Contabilidade Pública - Princípios Orçamentários$qq$, $qq$FAFIPA - OfAd (CM Campina GS)/CM Campina G do Sul/2014$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$O ciclo orçamentário, também chamado de processo orçamentário, é composto pelas fases: Elaboração da proposta pelo Poder Executivo, apreciação da proposta pelo Legislativo, execução do processo e controle e avaliação da execução. Além dessas fases, é importante seguir alguns princípios definidos na Lei nº. 4.320/64, quanto a estes princípios é CORRETO afirmar:$qq$, $qq$[["A", "O Princípio de exclusividade rege que o orçamento não deva conter apenas matéria orçamentária, mas incluir em seu projeto de lei assuntos adversos à previsão de receitas."], ["B", "O Princípio do Equilíbrio estabelece que as despesas devem ultrapassar as receitas."], ["C", "O Princípio da especificação define que o orçamento só possuirá a previsão ou a fixação de receitas."], ["D", "O Princípio da Publicidade que determina que a lei orçamentária deve estar acessível por meio de divulgação pública."]]$qq$::jsonb, $qq$D$qq$, 2014, 81, 1102, $qq$A$qq$, $qq${"cobranca": "Princípios orçamentários", "regra": "Publicidade exige divulgação dos atos e leis orçamentárias. Exclusividade impede matéria estranha à LOA, equilíbrio não significa despesas maiores que receitas e especificação detalha receitas e despesas.", "passos": ["1) A alternativa A descreve justamente o contrário da exclusividade.", "2) B está errada porque equilíbrio não significa despesas superiores às receitas.", "3) C está errada porque especificação não significa escolher entre previsão de receita ou fixação de despesa.", "4) D está correta: publicidade exige divulgação pública."], "calculo": "Não há cálculo.", "correta": "D) O princípio da publicidade determina que a lei orçamentária seja divulgada e acessível publicamente.", "erradas": ["A) Inverte a regra da exclusividade.", "B) Inverte o sentido do equilíbrio.", "C) Descreve incorretamente a especificação."], "fundamento": "Constituição Federal, art. 37, caput; Lei nº 4.320/1964; MCASP.", "pegadinha": "A alternativa D é a única que relaciona corretamente publicidade com divulgação e acesso público."}$qq$::jsonb, $qq$O ciclo orçamentário, também chamado de processo orçamentário, é composto pelas fases: Elaboração da proposta pelo Poder Executivo, apreciação da proposta pelo Legislativo, execução do processo e controle e avaliação da execução. Além dessas fases, é importante seguir alguns princípios definidos na Lei nº. 4.320/64, quanto a estes princípios é CORRETO afirma…$qq$),
($qq$3936137$qq$, 167, $qq$AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)$qq$, $qq$FAFIPA - PSP (SESA PR)/SESA PR/Contador/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$O texto seguinte servirá de base para responder à questão abaixo. No exercício financeiro de 2025, o Município de Capital do Vinho apresentou as seguintes operações orçamentárias e financeiras (em R$): Despesa Fixada na Lei Orçamentária 25.000.000,00 Anual Operações de Crédito por Antecipação de 270.000,00 Receita Orçamentária (ARO) Empenho Inscritos em Restos a Pagar 380.000,00 Processados Despesa Orçamentária Anual                                      22.750.000,00 Receita Prevista na Lei Orçamentária 25.000.000,00 Anual Recebimento de Cauções em garantia de 80.000,00 Contratos Restos a Pagar de 2023 pagos no 200.000,00 exercício de 2025 Empenhos Inscritos em Restos a Pagar 130.000,00 Não Processados Receita Arrecadada                                          23.800.000,00 De acordo com os dados fornecidos, é CORRETO afirmar que o resultado orçamentário do Município de Capital do Vinho no exercício financeiro de 2025 foi:$qq$, $qq$[["A", "um superávit de R$ 810.000,00."], ["B", "um déficit de R$ 320.000,00."], ["C", "um superávit de R$ 320.000,00."], ["D", "um déficit de R$ 540.000,00."], ["E", "um superávit de R$ 540.000,00."]]$qq$::jsonb, $qq$E$qq$, 2026, 314, 1101, $qq$A$qq$, $qq${"cobranca": "Balanço Orçamentário / resultado orçamentário", "regra": "O resultado orçamentário é obtido comparando a receita orçamentária realizada com a despesa orçamentária empenhada, conforme a estrutura do Balanço Orçamentário. Operações extraorçamentárias não entram nessa comparação.", "passos": ["1) Receita arrecadada = R$ 23.800.000.", "2) Despesa orçamentária anual = R$ 22.750.000.", "3) Resultado = 23.800.000 − 22.750.000 = R$ 1.050.000 de superávit.", "4) Nenhuma alternativa apresenta R$ 1.050.000.", "5) Portanto, há inconsistência entre os dados transcritos e o gabarito/alternativas."], "calculo": "R$ 23.800.000 − R$ 22.750.000 = R$ 1.050.000 de superávit.", "correta": "Os dados transcritos não permitem confirmar a alternativa E (R$ 540.000). Pelo cálculo direto do resultado orçamentário com os valores apresentados, o resultado é superávit de R$ 1.050.000.", "erradas": ["A) R$ 810.000 não resulta da diferença entre receita arrecadada e despesa orçamentária informadas.", "B) R$ 320.000 não resulta dos dados.", "C) R$ 320.000 também não.", "D) R$ 540.000 de déficit não decorre dos dados.", "E) R$ 540.000 de superávit não decorre dos dados apresentados."], "fundamento": "Lei nº 4.320/1964; MCASP, Balanço Orçamentário.", "pegadinha": "Não misturar restos a pagar, cauções e ARO no resultado orçamentário. Aqui, porém, mesmo isolando a execução orçamentária, os números fornecidos não fecham com as alternativas.", "verificacao": "Conferir a imagem/PDF original da questão 3936137; pode haver valor transcrito incorretamente no material extraído."}$qq$::jsonb, $qq$O texto seguinte servirá de base para responder à questão abaixo. No exercício financeiro de 2025, o Município de Capital do Vinho apresentou as seguintes operações orçamentárias e financeiras (em R$): Despesa Fixada na Lei Orçamentária 25.000.000,00 Anual Operações de Crédito por Antecipação de 270.000,00 Receita Orçamentária (ARO) Empenho Inscritos em Rest…$qq$),
($qq$4074897$qq$, 168, $qq$AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)$qq$, $qq$FAFIPA - Tes (CM Campo Largo)/CM Campo Largo/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Ao final do exercício, determinado Município elaborou a demonstração contábil aplicada ao setor público destinada a evidenciar, de forma comparativa, as receitas previstas e realizadas, bem como as despesas fixadas e executadas no orçamento. Nos termos da Lei nº 4.320/1964 e do MCASP, essa demonstração corresponde ao:$qq$, $qq$[["A", "Balanço Financeiro."], ["B", "Balanço Orçamentário."], ["C", "Relatório Resumido da Execução Orçamentária."], ["D", "Balanço Patrimonial."], ["E", "Demonstração das Variações Patrimoniais."]]$qq$::jsonb, $qq$B$qq$, 2026, 315, 1101, $qq$A$qq$, $qq${"cobranca": "Balanço Orçamentário", "regra": "O Balanço Orçamentário evidencia as receitas por categoria econômica, confrontando previsão e realização, e as despesas por categorias, confrontando fixação e execução.", "passos": ["1) O enunciado fala em receitas previstas e realizadas.", "2) Também fala em despesas fixadas e executadas.", "3) Essa é a finalidade do Balanço Orçamentário."], "calculo": "Não há cálculo.", "correta": "B) Balanço Orçamentário.", "erradas": ["A) Balanço Financeiro evidencia ingressos e dispêndios e saldos financeiros.", "C) RREO é relatório fiscal, não a demonstração contábil descrita.", "D) Balanço Patrimonial evidencia ativos, passivos e patrimônio líquido/saldo patrimonial.", "E) DVP evidencia variações patrimoniais aumentativas e diminutivas."], "fundamento": "Lei nº 4.320/1964, art. 102; MCASP, DCASP.", "pegadinha": "A expressão “previstas x realizadas” + “fixadas x executadas” identifica o Balanço Orçamentário."}$qq$::jsonb, $qq$Ao final do exercício, determinado Município elaborou a demonstração contábil aplicada ao setor público destinada a evidenciar, de forma comparativa, as receitas previstas e realizadas, bem como as despesas fixadas e executadas no orçamento. Nos termos da Lei nº 4.320/1964 e do MCASP, essa demonstração corresponde ao:$qq$),
($qq$4098504$qq$, 169, $qq$AFO, Direito Financeiro e Contabilidade Pública - Balanço Orçamentário (MCASP e NBC TSP 13)$qq$, $qq$FAFIPA - Ana (CRC PR)/CRC PR/Contábil/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Avalie os dados a seguir, extraídos do sistema contábil de um Conselho Regional de Contabilidade (CRC), todos posicionados em 31/12/2025. Crédito especial autorizado pela plenária em 15 de novembro de 2024 e legalmente reaberto no exercício de 2025: R$35.000,00. Reserva de contingência fixada na Lei Orçamentária Anual de 2025: R$50.000,00. Superávit financeiro de exercícios anteriores (apurado no Balanço Patrimonial de 2024 e utilizado como fonte para abertura de créditos em 2025): R$120.000,00. Recursos arrecadados em exercícios anteriores (fundos específicos vinculados disponíveis no caixa da autarquia): R$40.000,00. Inscrição de Restos a Pagar Processados (referentes a despesas de 2025 que foram liquidadas, mas não pagas até o final do ano): R$20.000,00. Considerando as diretrizes do Manual de Contabilidade Aplicada ao Setor Público (MCASP), assinale a alternativa que indica o valor CORRETO que deve ser reportado na linha "Saldos de Exercícios Anteriores" do Quadro Principal do Balanço Orçamentário de 2025.$qq$, $qq$[["A", "R$ 245.000,00."], ["B", "R$ 155.000,00."], ["C", "R$ 160.000,00."], ["D", "R$ 215.000,00."], ["E", "R$ 195.000,00.  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                             32/57"]]$qq$::jsonb, $qq$E$qq$, 2026, 316, 1101, $qq$A$qq$, $qq${"cobranca": "Balanço Orçamentário — Saldos de Exercícios Anteriores", "regra": "No Quadro Principal do Balanço Orçamentário, a linha “Saldos de Exercícios Anteriores” evidencia recursos de exercícios anteriores utilizados para abertura/reabertura de créditos adicionais, conforme a estrutura do MCASP.", "passos": ["1) Crédito especial reaberto: R$ 35.000 → entra como saldo de exercício anterior utilizado.", "2) Superávit financeiro utilizado como fonte: R$ 120.000 → entra.", "3) Recursos arrecadados em exercícios anteriores/fundos específicos disponíveis: R$ 40.000 → conforme o enunciado, compõem os saldos de exercícios anteriores reportados.", "4) Reserva de contingência de 2025 não é saldo de exercício anterior.", "5) Restos a pagar processados inscritos em 2025 também não compõem essa linha.", "6) Soma: 35.000 + 120.000 + 40.000 = R$ 195.000."], "calculo": "R$ 35.000 + R$ 120.000 + R$ 40.000 = R$ 195.000.", "correta": "E) R$ 195.000,00.", "erradas": ["A) Inclui valores que não devem ser somados à linha.", "B) Não considera corretamente todos os recursos de exercícios anteriores.", "C) Omite o crédito especial reaberto.", "D) Também incorpora valor indevido."], "fundamento": "MCASP 11ª edição — Balanço Orçamentário, Quadro Principal.", "pegadinha": "Não somar reserva de contingência nem restos a pagar como se fossem “saldo de exercício anterior”."}$qq$::jsonb, $qq$Avalie os dados a seguir, extraídos do sistema contábil de um Conselho Regional de Contabilidade (CRC), todos posicionados em 31/12/2025. Crédito especial autorizado pela plenária em 15 de novembro de 2024 e legalmente reaberto no exercício de 2025: R$35.000,00. Reserva de contingência fixada na Lei Orçamentária Anual de 2025: R$50.000,00. Superávit financei…$qq$),
($qq$3598405$qq$, 170, $qq$AFO, Direito Financeiro e Contabilidade Pública - Balanço Patrimonial (AFO e CPU)$qq$, $qq$FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Com base nas definições legais e nos conceitos sobre Ativo e Passivo para elaboração do Balanço Patrimonial previstos na Lei Federal nº 4.320/1964, assinale a alternativa INCORRETA.$qq$, $qq$[["A", "O Passivo Permanente inclui as dívidas fundadas e outras que dependem de autorização legislativa para amortização ou resgate."], ["B", "O Ativo Financeiro é composto por créditos e valores realizáveis independentemente de autorização orçamentária e também pelos saldos disponíveis em caixa e bancos."], ["C", "O Ativo Permanente compreende os bens e direitos cuja mobilização ou alienação dependa de autorização legislativa, como terrenos, prédios e participações permanentes."], ["D", "O Passivo Financeiro é composto exclusivamente pelas obrigações que foram objeto de crédito adicional, e por isso sua quitação depende de autorização legislativa específica."]]$qq$::jsonb, $qq$D$qq$, 2025, 170, 1100, $qq$A$qq$, $qq${"cobranca": "Balanço Patrimonial — Ativo e Passivo Financeiro/Permanente", "regra": "O Passivo Financeiro não é formado exclusivamente por obrigações decorrentes de créditos adicionais. Pela Lei nº 4.320/1964, ele compreende compromissos exigíveis cujo pagamento independa de autorização orçamentária.", "passos": ["1) A, B e C reproduzem conceitos compatíveis com a classificação legal tradicional.", "2) D afirma que o Passivo Financeiro é composto exclusivamente por obrigações objeto de crédito adicional.", "3) Isso é falso: a classificação decorre da exigibilidade e da independência de autorização orçamentária, não da existência de crédito adicional."], "calculo": "Não há cálculo.", "correta": "D) É a alternativa INCORRETA.", "erradas": ["A) Compatível com a definição legal do passivo permanente.", "B) Compatível com o ativo financeiro.", "C) Compatível com a definição de ativo permanente na estrutura da Lei nº 4.320/1964."], "fundamento": "Lei nº 4.320/1964, arts. 105 e 106.", "pegadinha": "A banca troca o critério de classificação do Passivo Financeiro por uma suposta origem em crédito adicional."}$qq$::jsonb, $qq$Com base nas definições legais e nos conceitos sobre Ativo e Passivo para elaboração do Balanço Patrimonial previstos na Lei Federal nº 4.320/1964, assinale a alternativa INCORRETA.$qq$),
($qq$3599091$qq$, 171, $qq$AFO, Direito Financeiro e Contabilidade Pública - Balanço Patrimonial (AFO e CPU)$qq$, $qq$FAFIPA - Cont (CICA)/CICA/2025$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$Em relação ao que dispõe o Manual de Contabilidade Aplicada ao Setor Público (MCASP) - 10º Edição a respeito da avaliação e mensuração dos elementos patrimoniais nas entidades do setor público, assinale a alternativa CORRETA.$qq$, $qq$[["A", "Reavaliação é a adoção do valor de mercado ou de consenso entre as partes para bens do ativo."], ["B", "Quando um item do ativo imobilizado é reavaliado, a depreciação acumulada na data da reavaliação deve ser eliminada contra o valor contábil líquido do ativo, atualizando-se o seu valor bruto pelo valor reavaliado."], ["C", "Se o valor contábil de uma classe do ativo diminuir em virtude da reavaliação e houver saldo de reserva de reavaliação, a diminuição do ativo deve ser reconhecida no resultado do período."], ["D", "Diferentemente dos ativos imobilizado, os ativos intangíveis não podem ser reavaliados em nenhuma hipótese."]]$qq$::jsonb, $qq$A$qq$, 2025, 171, 1100, $qq$A$qq$, $qq${"cobranca": "Avaliação e mensuração — reavaliação do ativo", "regra": "Reavaliação é a adoção do valor de mercado ou de consenso entre as partes para ativos, quando permitida pelas normas. A mensuração subsequente possui regras específicas para depreciação acumulada e efeitos no patrimônio.", "passos": ["1) A define reavaliação como adoção de valor de mercado ou consenso entre as partes → correta.", "2) B descreve um tratamento que não deve ser generalizado dessa forma para todos os casos de reavaliação.", "3) C também está incorreta porque uma diminuição pode ser reconhecida contra eventual reserva de reavaliação até o limite existente, conforme a situação.", "4) D é absoluta ao afirmar que intangíveis nunca podem ser reavaliados, o que não corresponde à norma quando existe mercado ativo."], "calculo": "Não há cálculo.", "correta": "A) Reavaliação é a adoção do valor de mercado ou de consenso entre as partes para bens do ativo.", "erradas": ["B) Generaliza o procedimento de eliminação da depreciação acumulada.", "C) Ignora o tratamento contra eventual reserva existente.", "D) É absoluta: a possibilidade depende da existência de mercado ativo e das condições normativas."], "fundamento": "MCASP, capítulo de avaliação e mensuração; NBC TSP aplicáveis ao ativo imobilizado e intangível.", "pegadinha": "Cuidado com alternativas absolutas como “em nenhuma hipótese”."}$qq$::jsonb, $qq$Em relação ao que dispõe o Manual de Contabilidade Aplicada ao Setor Público (MCASP) - 10º Edição a respeito da avaliação e mensuração dos elementos patrimoniais nas entidades do setor público, assinale a alternativa CORRETA.$qq$),
($qq$3936167$qq$, 172, $qq$AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de PPA, LDO e LOA$qq$, $qq$FAFIPA - PSP (SESA PR)/SESA PR/Contador/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$As normas constitucionais que disciplinam as finanças públicas estruturam um sistema integrado de planejamento e orçamento, composto por três instrumentos fundamentais: o Plano Plurianual (PPA), a Lei de Diretrizes Orçamentárias (LDO) e a Lei Orçamentária Anual (LOA). Sobre as disposições constitucionais que regem esses instrumentos, considere as assertivas a seguir. I. O Plano Plurianual (PPA) estabelece as prioridades e metas da administração pública para um período de quatro anos, devendo ser encaminhado pelo Chefe do Poder Executivo até oito meses e meio antes do encerramento do primeiro exercício financeiro do mandato presidencial e devolvido para sanção até o encerramento da sessão legislativa. II. A Lei de Diretrizes Orçamentárias (LDO) disporá, dentre outros temas, sobre as alterações na legislação tributária e estabelecerá a política de aplicação das agências financeiras oficiais de fomento. III. A Lei Orçamentária Anual (LOA) pode conter autorização para abertura de créditos suplementares, desde que atendidos os requisitos constitucionais e legais, sendo vedada a inclusão, no projeto da LOA, de dispositivo estranho à previsão da receita e à fixação da despesa. Está CORRETO o que se afirma em:$qq$, $qq$[["A", "III, apenas."], ["B", "I, II e III."], ["C", "II e III, apenas."], ["D", "I e II, apenas."], ["E", "I e III, apenas.  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                                19/57"]]$qq$::jsonb, $qq$C$qq$, 2026, 270, 1098, $qq$A$qq$, $qq${"cobranca": "PPA, LDO e LOA — Constituição Federal", "regra": "A LDO orienta a elaboração da LOA e dispõe sobre alterações na legislação tributária e política de aplicação das agências financeiras oficiais de fomento. A LOA pode autorizar créditos suplementares, respeitados os requisitos legais. O PPA possui vigência de quatro anos.", "passos": ["1) I está incorreta porque os prazos constitucionais de encaminhamento do PPA não correspondem ao texto apresentado.", "2) II está correta: art. 165, § 2º, inclui alterações na legislação tributária e política de aplicação das agências oficiais de fomento.", "3) III está correta: a LOA pode conter autorização para abertura de créditos suplementares e deve respeitar a exclusividade.", "4) Logo, somente II e III estão corretas."], "calculo": "Não há cálculo.", "correta": "C) II e III, apenas.", "erradas": ["A) Incorreta porque II também é verdadeira.", "B) Incorreta porque I é falsa.", "D) Incorreta porque I é falsa.", "E) Incorreta porque I é falsa."], "fundamento": "Constituição Federal, art. 165, §§ 2º, 5º e 8º.", "pegadinha": "Atenção aos prazos constitucionais do PPA: a questão usa um prazo incorreto na afirmativa I."}$qq$::jsonb, $qq$As normas constitucionais que disciplinam as finanças públicas estruturam um sistema integrado de planejamento e orçamento, composto por três instrumentos fundamentais: o Plano Plurianual (PPA), a Lei de Diretrizes Orçamentárias (LDO) e a Lei Orçamentária Anual (LOA). Sobre as disposições constitucionais que regem esses instrumentos, considere as assertivas …$qq$),
($qq$3937563$qq$, 173, $qq$AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de PPA, LDO e LOA$qq$, $qq$FAFIPA - PSP (SESA PR)/SESA PR/Economista/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$No ciclo que envolve o planejamento, priorização e execução de um gasto público, o setor público utiliza três peças orçamentárias fundamentais: o Plano Plurianual (PPA), a Lei de Diretrizes Orçamentárias (LDO) e a Lei de Orçamento Anual (LOA). Sobre esses elementos que compõem o orçamento público, assinale a alternativa CORRETA.$qq$, $qq$[["A", "A Lei Orçamentária Anual (LOA), em virtude do princípio da anualidade, não permite previsões de despesas para exercícios seguintes, com a especificação dos investimentos plurianuais, como seria o caso de grandes complexos hospitalares já iniciados em anos anteriores."], ["B", "A Lei de Diretrizes Orçamentárias (LDO) compreende a priorização da administração pública e serve de guia para a elaboração da lei orçamentária anual. Na LDO, não é possível realizar alterações na legislação tributária nem definir política de aplicação das agências financeiras oficiais de fomento."], ["C", "A concessão de qualquer vantagem ou aumento de remuneração, a criação de cargos, empregos e funções ou alteração de estrutura de carreiras, bem como a admissão ou contratação de pessoal, a qualquer título, pelos órgãos e entidades da administração direta ou indireta, inclusive fundações instituídas e mantidas pelo poder público, só poderão ser feitas se houver autorização específica na lei de diretrizes orçamentárias, ressalvadas as empresas públicas e as sociedades de economia mista."], ["D", "A Lei de Orçamento Anual (LOA) compreende o orçamento fiscal do setor público. Não está incluído na LOA o orçamento de investimento das empresas em que a União, direta ou indiretamente, detenha a maioria do capital social com direito a voto."], ["E", "O Plano Plurianual (PPA) define as diretrizes, objetivos e metas para as despesas de duração continuada, como é o caso do Programa Nacional de Imunização. O PPA tem vigência de 4 anos e intercala os dois anos do primeiro mandato e os dois anos do mandato subsequente, para garantir a continuidade de programas para além dos ciclos políticos."]]$qq$::jsonb, $qq$C$qq$, 2026, 271, 1098, $qq$A$qq$, $qq${"cobranca": "PPA, LDO e LOA — regras constitucionais", "regra": "A LDO estabelece metas e prioridades e orienta a LOA; pode tratar de alterações tributárias e política de aplicação das agências oficiais. A Constituição também prevê autorização específica na LDO para determinadas despesas com pessoal, ressalvadas as empresas públicas e sociedades de economia mista. A LOA compreende orçamento fiscal, orçamento de investimento das empresas em que a União detenha maioria do capital votante e orçamento da seguridade social.", "passos": ["1) A está errada: investimentos plurianuais podem aparecer no planejamento e a anualidade não impede a continuidade de investimentos.", "2) B está errada porque a LDO pode tratar de alterações na legislação tributária e política de aplicação das agências.", "3) C reproduz o art. 169, § 1º, da CF, ressalvando empresas públicas e sociedades de economia mista.", "4) D está errada porque a LOA federal inclui o orçamento de investimento das empresas controladas pela União.", "5) E está errada ao descrever de forma incorreta a duração/intercalação do PPA."], "calculo": "Não há cálculo.", "correta": "C) A autorização específica na LDO é exigida nas hipóteses constitucionais de pessoal, com a ressalva indicada.", "erradas": ["A) Anualidade não elimina a programação plurianual.", "B) A LDO pode tratar dos dois temas citados.", "D) O orçamento de investimento integra a LOA nos termos constitucionais.", "E) O PPA tem quatro anos, mas não funciona pela “intercalação” descrita."], "fundamento": "Constituição Federal, arts. 165 e 169, § 1º.", "pegadinha": "A banca usa negativas absolutas (“não é possível”) e troca a composição da LOA para testar detalhes constitucionais."}$qq$::jsonb, $qq$No ciclo que envolve o planejamento, priorização e execução de um gasto público, o setor público utiliza três peças orçamentárias fundamentais: o Plano Plurianual (PPA), a Lei de Diretrizes Orçamentárias (LDO) e a Lei de Orçamento Anual (LOA). Sobre esses elementos que compõem o orçamento público, assinale a alternativa CORRETA.$qq$),
($qq$4092795$qq$, 174, $qq$AFO, Direito Financeiro e Contabilidade Pública - Tópicos Mesclados de PPA, LDO e LOA$qq$, $qq$FAFIPA - Tec Adm (Pref Prado Ferreira)/Pref Prado Ferreira/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$No Município de Prado Ferreira, o setor administrativo participou da elaboração das peças orçamentárias, observando os instrumentos de planejamento previstos na Constituição Federal. Durante uma reunião, foi discutida a função de cada instrumento no processo de planejamento governamental. Com base nos conceitos de orçamento público, assinale a alternativa CORRETA.$qq$, $qq$[["A", "O Plano Plurianual (PPA) estabelece as metas e prioridades da Administração Pública apenas para o período de um ano."], ["B", "O orçamento público é um instrumento exclusivamente contábil, sem relação com o planejamento das ações governamentais."], ["C", "A Lei de Diretrizes Orçamentárias (LDO) tem como principal função fixar detalhadamente todas as despesas do exercício financeiro."], ["D", "A Lei Orçamentária Anual (LOA) estima as receitas e fixa as despesas para o exercício financeiro."], ["E", "A LDO substitui o PPA na definição dos programas de governo de longo prazo."]]$qq$::jsonb, $qq$D$qq$, 2026, 272, 1098, $qq$A$qq$, $qq${"cobranca": "Função da LOA", "regra": "A Lei Orçamentária Anual estima as receitas e fixa as despesas para o exercício financeiro.", "passos": ["1) A reduz o PPA a um ano, o que está errado.", "2) B trata o orçamento como instrumento apenas contábil, ignorando sua função de planejamento.", "3) C atribui à LDO a função detalhada de fixar todas as despesas, que é da LOA.", "4) D corresponde à definição constitucional/legal da LOA.", "5) E também está errada porque LDO não substitui PPA."], "calculo": "Não há cálculo.", "correta": "D) A LOA estima as receitas e fixa as despesas para o exercício financeiro.", "erradas": ["A) Função de médio prazo é do PPA.", "B) Orçamento também é instrumento de planejamento e gestão.", "C) A LDO orienta a elaboração da LOA; não substitui sua função de fixação detalhada da despesa.", "E) PPA e LDO têm funções distintas."], "fundamento": "Constituição Federal, art. 165; Lei nº 4.320/1964.", "pegadinha": "Memorize a tríade: PPA = diretrizes, objetivos e metas; LDO = metas/prioridades e orientação; LOA = estima receita e fixa despesa."}$qq$::jsonb, $qq$No Município de Prado Ferreira, o setor administrativo participou da elaboração das peças orçamentárias, observando os instrumentos de planejamento previstos na Constituição Federal. Durante uma reunião, foi discutida a função de cada instrumento no processo de planejamento governamental. Com base nos conceitos de orçamento público, assinale a alternativa CO…$qq$),
($qq$4098545$qq$, 175, $qq$AFO, Direito Financeiro e Contabilidade Pública - Demonstração das Variações Patrimoniais (DVP)$qq$, $qq$FAFIPA - Ana (CRC PR)/CRC PR/Contábil/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Avalie os dados a seguir, extraídos do quadro resumido da Demonstração das Variações Patrimoniais (DVP) de um Conselho Regional de Contabilidade (CRC), que apresenta a comparação entre o exercício atual e o anterior. Demonstração das Variações                    Exercício Atual           Exercício Anterior Patrimoniais Variações Patrimoniais X                  R$ 15.500.000,00 Aumentativas (VPA) Variações Patrimoniais R$ 16.000.000,00                    Y Diminutivas (VPD) Resultado Patrimonial R$ 2.000.000,00            R$ 3.500.000,00 do Período Considerando a estrutura da DVP exigida pelo Manual de Contabilidade Aplicado ao Setor Público (MCASP) e o regime contábil aplicável ao setor público, a partir da análise das informações fornecidas, é CORRETO afirmar que:$qq$, $qq$[["A", "as variações patrimoniais qualitativas (fatos permutativos) foram as principais responsáveis pela redução do resultado patrimonial apurado no exercício atual."], ["B", "a economia orçamentária no exercício atual gerou uma redução das despesas patrimoniais e, consequentemente, um maior resultado patrimonial."], ["C", "houve frustração generalizada na arrecadação de anuidades no exercício atual, o que gerou um volume de VPAs inferior ao total de VPDs incorridas."], ["D", "as VPDs apresentaram maior variação absoluta do que as VPAs no exercício atual em relação ao anterior, justificando a queda no resultado patrimonial."], ["E", "as VPAs do exercício atual foram menores do que aquelas reconhecidas no exercício anterior."]]$qq$::jsonb, $qq$D$qq$, 2026, 336, 1098, $qq$A$qq$, $qq${"cobranca": "Demonstração das Variações Patrimoniais — resultado patrimonial", "regra": "Na DVP, o resultado patrimonial decorre da diferença entre Variações Patrimoniais Aumentativas (VPA) e Variações Patrimoniais Diminutivas (VPD).", "passos": ["1) Exercício atual: VPD = R$ 16.000.000 e resultado = R$ 2.000.000. Logo, VPA atual = R$ 18.000.000.", "2) Exercício anterior: VPA = R$ 15.500.000 e resultado = R$ 3.500.000. Logo, VPD anterior = R$ 12.000.000.", "3) Variação absoluta da VPA = 18,0 − 15,5 = R$ 2,5 milhões.", "4) Variação absoluta da VPD = 16,0 − 12,0 = R$ 4,0 milhões.", "5) A VPD apresentou maior variação absoluta, contribuindo para a queda do resultado de R$ 3,5 milhões para R$ 2,0 milhões."], "calculo": "VPA atual = 16.000.000 + 2.000.000 = R$ 18.000.000; VPD anterior = 15.500.000 − 3.500.000 = R$ 12.000.000; variação VPA = R$ 2,5 mi; variação VPD = R$ 4,0 mi.", "correta": "D) As VPDs apresentaram maior variação absoluta do que as VPAs no exercício atual em relação ao anterior, justificando a queda no resultado patrimonial.", "erradas": ["A) Não há dados que permitam atribuir a queda a variações qualitativas.", "B) Economia orçamentária não é automaticamente redução de VPD patrimonial.", "C) A DVP não permite concluir “frustração generalizada” de anuidades.", "E) É falsa: a VPA atual foi R$ 18 milhões, maior que os R$ 15,5 milhões anteriores."], "fundamento": "MCASP 11ª edição — Demonstração das Variações Patrimoniais.", "pegadinha": "Não confundir resultado orçamentário com resultado patrimonial; a DVP trabalha com VPA e VPD."}$qq$::jsonb, $qq$Avalie os dados a seguir, extraídos do quadro resumido da Demonstração das Variações Patrimoniais (DVP) de um Conselho Regional de Contabilidade (CRC), que apresenta a comparação entre o exercício atual e o anterior. Demonstração das Variações                    Exercício Atual           Exercício Anterior Patrimoniais Variações Patrimoniais X               …$qq$),
($qq$3936135$qq$, 176, $qq$AFO, Direito Financeiro e Contabilidade Pública - Balanço Financeiro$qq$, $qq$FAFIPA - PSP (SESA PR)/SESA PR/Contador/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$O texto seguinte servirá de base para responder à questão abaixo. No exercício financeiro de 2025, o Município de Capital do Vinho apresentou as seguintes operações orçamentárias e financeiras (em R$): Despesa Fixada na Lei Orçamentária 25.000.000,00 Anual Operações de Crédito por Antecipação de 270.000,00 Receita Orçamentária (ARO) Empenho Inscritos em Restos a Pagar 380.000,00 Processados Despesa Orçamentária Anual                                      22.750.000,00 Receita Prevista na Lei Orçamentária 25.000.000,00 Anual Recebimento de Cauções em garantia de 80.000,00 Contratos Restos a Pagar de 2023 pagos no 200.000,00 exercício de 2025 Empenhos Inscritos em Restos a Pagar 130.000,00 Não Processados Receita Arrecadada                                         23.800.000,00 Ainda com base nos dados, é CORRETO afirmar que o Balanço Financeiro do Município de Capital do Vinho, encerrado em 31/12/2025, evidenciará, na linha "Ingressos Extraorçamentários", o valor de:$qq$, $qq$[["A", "R$ 730.000,00."], ["B", "R$ 350.000,00."], ["C", "R$ 480.000,00."], ["D", "R$ 860.000,00."], ["E", "R$ 780.000,00."]]$qq$::jsonb, $qq$D$qq$, 2026, 358, 1098, $qq$A$qq$, $qq${"cobranca": "Balanço Financeiro — ingressos extraorçamentários", "regra": "Ingressos extraorçamentários incluem, entre outros, depósitos/cauções, operações de crédito por antecipação da receita e inscrição de restos a pagar. Pagamentos de restos a pagar são dispêndios extraorçamentários, não ingressos.", "passos": ["1) ARO = R$ 270.000 → ingresso extraorçamentário.", "2) Cauções = R$ 80.000 → ingresso extraorçamentário.", "3) Restos a pagar processados inscritos = R$ 380.000 → ingresso extraorçamentário.", "4) Restos a pagar não processados inscritos = R$ 130.000 → ingresso extraorçamentário.", "5) RP de 2023 pagos = R$ 200.000 → dispêndio extraorçamentário, portanto não entra nos ingressos.", "6) Soma = 270.000 + 80.000 + 380.000 + 130.000 = R$ 860.000."], "calculo": "R$ 270.000 + R$ 80.000 + R$ 380.000 + R$ 130.000 = R$ 860.000.", "correta": "D) R$ 860.000,00.", "erradas": ["A) Inclui/exclui valores de forma incompatível com a estrutura do BF.", "B) R$ 350.000 corresponde apenas a parte dos ingressos.", "C) R$ 480.000 não considera todos os restos a pagar inscritos.", "E) R$ 780.000 não corresponde à soma dos ingressos extraorçamentários."], "fundamento": "Lei nº 4.320/1964, art. 103; MCASP — Balanço Financeiro.", "pegadinha": "Inscrição de RP entra como ingresso extraorçamentário; pagamento de RP entra como dispêndio extraorçamentário."}$qq$::jsonb, $qq$O texto seguinte servirá de base para responder à questão abaixo. No exercício financeiro de 2025, o Município de Capital do Vinho apresentou as seguintes operações orçamentárias e financeiras (em R$): Despesa Fixada na Lei Orçamentária 25.000.000,00 Anual Operações de Crédito por Antecipação de 270.000,00 Receita Orçamentária (ARO) Empenho Inscritos em Rest…$qq$),
($qq$4074895$qq$, 177, $qq$AFO, Direito Financeiro e Contabilidade Pública - Balanço Financeiro$qq$, $qq$FAFIPA - Tes (CM Campo Largo)/CM Campo Largo/2026$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Na elaboração do Balanço Financeiro, o ente público deve utilizar informações extraídas das classes do Plano de Contas Aplicado ao Setor Público (PCASP), conforme a natureza dos registros evidenciados. Com base no Manual de Contabilidade Aplicada ao Setor Público — MCASP, 11ª edição, considere as assertivas a seguir. I. A execução da receita orçamentária e da despesa orçamentária evidenciada no Balanço Financeiro é obtida a partir das contas da classe 6, relacionada aos controles da execução do planejamento e orçamento. II. Os recebimentos e pagamentos extraorçamentários, bem como os saldos em espécie do exercício anterior e para o exercício seguinte, são evidenciados com base em contas patrimoniais das classes 1 e 2. III. As classes 3 e 4 substituem as classes patrimoniais na evidenciação dos saldos de caixa e equivalentes de caixa, por registrarem as variações patrimoniais diminutivas e aumentativas. IV. As classes 7 e 8 são utilizadas para registrar diretamente a execução da receita e da despesa orçamentária no Balanço Financeiro. Está CORRETO o que se afirma em:$qq$, $qq$[["A", "III e IV, apenas."], ["B", "II e III, apenas."], ["C", "I e II, apenas."], ["D", "I, apenas."], ["E", "II, apenas."]]$qq$::jsonb, $qq$C$qq$, 2026, 359, 1098, $qq$A$qq$, $qq${"cobranca": "Balanço Financeiro — classes do PCASP", "regra": "A execução da receita e da despesa orçamentária no Balanço Financeiro é obtida das contas da classe 6, ligada aos controles da execução do planejamento e orçamento. As informações patrimoniais relacionadas a ingressos/pagamentos extraorçamentários e saldos em espécie são obtidas conforme as contas patrimoniais pertinentes.", "passos": ["1) I está correta: a execução orçamentária é evidenciada com base na classe 6.", "2) II está correta no enquadramento adotado pela questão para ingressos/pagamentos extraorçamentários e saldos em espécie.", "3) III é falsa: classes 3 e 4 registram VPD e VPA, não substituem as classes patrimoniais para caixa.", "4) IV é falsa: classes 7 e 8 são de controle, não registram diretamente a execução orçamentária como afirmado.", "5) Portanto, I e II estão corretas."], "calculo": "Não há cálculo.", "correta": "C) I e II, apenas.", "erradas": ["A) III e IV são falsas.", "B) III é falsa.", "D) II também está correta.", "E) I também está correta."], "fundamento": "MCASP 11ª edição; PCASP — classes e natureza das informações contábeis.", "pegadinha": "Memorize as classes: 1 e 2 = patrimoniais; 3 e 4 = VPD/VPA; 5 e 6 = controles da execução orçamentária; 7 e 8 = controles."}$qq$::jsonb, $qq$Na elaboração do Balanço Financeiro, o ente público deve utilizar informações extraídas das classes do Plano de Contas Aplicado ao Setor Público (PCASP), conforme a natureza dos registros evidenciados. Com base no Manual de Contabilidade Aplicada ao Setor Público — MCASP, 11ª edição, considere as assertivas a seguir. I. A execução da receita orçamentária e d…$qq$),
($qq$3435208$qq$, 178, $qq$AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública$qq$, $qq$FAFIPA - Cont (Pref São Mateus do S)/Pref São Mateus do S/2025$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                                  7/57 227) Uma Prefeitura Municipal está executando seu orçamento para o exercício de 2025 e precisa classificar corretamente os empenhos das seguintes despesas. •Despesa 1: pagamento de aluguel de um prédio onde funciona uma unidade administrativa da prefeitura. O contrato tem um valor anual fixo de R$240.000,00, pago em parcelas mensais de R$ 20.000,00. •Despesa 2: aquisição de materiais de escritório para o departamento de finanças, cujo valor total é conhecido e será pago em uma única parcela nomomento da entrega. •Despesa 3: pagamento de contas de energia elétrica e abastecimento de água de prédios públicos municipais, cujo valor varia conforme o consumomensal. Com base na Lei Federal nº 4.320/1964, as despesas apresentadas devem ser classificadas nos seguintes tipos de empenho:$qq$, $qq$[["A", "Despesa 1: Empenho Estimativo; Despesa 2: Empenho Ordinário; Despesa 3: Empenho Global."], ["B", "Despesa 1: Empenho Global; Despesa 2: Empenho Estimativo; Despesa 3: Empenho Ordinário."], ["C", "Despesa 1: Empenho Ordinário; Despesa 2: Empenho Estimativo; Despesa 3: Empenho Global."], ["D", "Despesa 1: Empenho Ordinário; Despesa 2: Empenho Global; Despesa 3: Empenho Estimativo."], ["E", "Despesa 1: Empenho Global; Despesa 2: Empenho Ordinário; Despesa 3: Empenho Estimativo."]]$qq$::jsonb, $qq$E$qq$, 2025, null, 1097, $qq$A$qq$, $qq${"cobranca": "Tipos de empenho", "regra": "Empenho global é adequado a despesas contratuais e parceladas de valor determinado; empenho ordinário a despesa cujo valor é conhecido e pago de uma vez; empenho estimativo a despesas cujo montante não pode ser previamente determinado.", "passos": ["1) Aluguel anual fixo de R$ 240.000, pago mensalmente → empenho global.", "2) Material de escritório com valor total conhecido e pagamento único → empenho ordinário.", "3) Água e energia com valor variável → empenho estimativo.", "4) A sequência é Global, Ordinário, Estimativo."], "calculo": "Aluguel anual: 12 × R$ 20.000 = R$ 240.000, valor determinado e parcelado → global.", "correta": "E) Despesa 1: Global; Despesa 2: Ordinário; Despesa 3: Estimativo.", "erradas": ["A) Troca global por estimativo na despesa 1.", "B) Troca ordinário/estimativo.", "C) Troca as três classificações.", "D) Trata a aquisição como global, embora o pagamento seja único."], "fundamento": "Lei nº 4.320/1964, art. 60; classificação tradicional dos tipos de empenho.", "pegadinha": "O fato de uma despesa ser paga mensalmente não a torna estimativa se o valor contratual total é determinado."}$qq$::jsonb, $qq$w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                                  7/57 227) Uma Prefeitura Municipal está executando seu orçamento para o exercício de 2025 e precisa classificar corretamente os empenhos das seguintes despesas. •Despesa 1: pagamento de aluguel de um p…$qq$),
($qq$3598399$qq$, 179, $qq$AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública$qq$, $qq$FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Uma Prefeitura Municipal está executando seu orçamento para o exercício de 2025 e precisa classificar corretamente os empenhos das seguintes despesas: - Despesa 1: pagamento mensal de R$ 8.500,00 referente a contrato de aluguel de um galpão alugado para uso da Secretaria Municipal de Obras, com valor contratual anual fixo de R$ 102.000,00. - Despesa 2: aquisição de cadeiras para salas de reunião da Secretaria de Administração. O valor total da compra é de R$ 18.000,00 e será pago integralmente no ato da entrega. - Despesa 3: pagamento mensal de contas de telefonia móvel institucional, cujos valores variam de acordo com o uso, sem valor fixo previamente determinado. Com base na legislação vigente e nos conceitos contábeis aplicados ao setor público, os tipos corretos de empenho para essas despesas são:$qq$, $qq$[["A", "Despesa 1: Empenho Ordinário; Despesa 2: Empenho Estimativo; Despesa 3: Empenho Global."], ["B", "Despesa 1: Empenho Estimativo; Despesa 2: Empenho Ordinário; Despesa 3: Empenho Global."], ["C", "Despesa 1: Empenho Global; Despesa 2: Empenho Ordinário; Despesa 3: Empenho Estimativo."], ["D", "Despesa 1: Empenho Ordinário; Despesa 2: Empenho Global; Despesa 3: Empenho Estimativo."]]$qq$::jsonb, $qq$C$qq$, 2025, 228, 1097, $qq$A$qq$, $qq${"cobranca": "Tipos de empenho", "regra": "Contrato anual com valor fixo e pagamento parcelado → global; aquisição com valor certo e pagamento integral → ordinário; serviço de consumo variável → estimativo.", "passos": ["1) Aluguel anual de R$ 102.000, pago mensalmente → global.", "2) Cadeiras por R$ 18.000, pagamento integral na entrega → ordinário.", "3) Telefonia variável → estimativo.", "4) A sequência corresponde à alternativa C."], "calculo": "R$ 8.500 × 12 = R$ 102.000; valor global conhecido e parcelado.", "correta": "C) Global; Ordinário; Estimativo.", "erradas": ["A) Classifica o aluguel como ordinário e a compra como estimativa.", "B) Inverte as três classificações.", "D) Classifica a compra como global, embora o pagamento seja integral."], "fundamento": "Lei nº 4.320/1964, art. 60; conceitos de empenho global, ordinário e estimativo.", "pegadinha": "O critério é valor determinado/parcelamento versus valor indeterminado, não simplesmente a periodicidade do pagamento."}$qq$::jsonb, $qq$Uma Prefeitura Municipal está executando seu orçamento para o exercício de 2025 e precisa classificar corretamente os empenhos das seguintes despesas: - Despesa 1: pagamento mensal de R$ 8.500,00 referente a contrato de aluguel de um galpão alugado para uso da Secretaria Municipal de Obras, com valor contratual anual fixo de R$ 102.000,00. - Despesa 2: aquis…$qq$),
($qq$3598421$qq$, 180, $qq$AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública$qq$, $qq$FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Sobre os estágios da execução da despesa orçamentária, julgue verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência CORRETA. (__) O empenho é o ato que cria para o ente público a obrigação de pagamento, representando a reserva da dotação orçamentária para determinada despesa. (__) A liquidação da despesa ocorre após o pagamento, e consiste na conferência da conciliação bancária referente à ordem de pagamento emitida. (__) O pagamento só pode ser realizado após a liquidação da despesa, e deve ser autorizado por despacho de autoridade competente. (__) O empenho estimativo é adequado para despesas de valor fixo e previamente determinado, como aquisição de equipamentos de informática via contrato com valor global.$qq$, $qq$[["A", "F, F, V, V."], ["B", "V, V, F, V."], ["C", "V, F, V, F."], ["D", "V, F, V, V."]]$qq$::jsonb, $qq$C$qq$, 2025, 229, 1097, $qq$A$qq$, $qq${"cobranca": "Estágios da despesa pública", "regra": "A execução da despesa passa por empenho, liquidação e pagamento. A liquidação verifica o direito adquirido pelo credor com base nos documentos e na prestação/entrega. O pagamento ocorre após a regular liquidação. Empenho estimativo é usado quando o montante não pode ser previamente determinado.", "passos": ["1) Primeira afirmativa: verdadeira no sentido adotado pela questão — o empenho reserva dotação e cria compromisso para o ente.", "2) Segunda: falsa, pois liquidação ocorre antes do pagamento.", "3) Terceira: verdadeira, pois pagamento depende da liquidação.", "4) Quarta: falsa, pois equipamento com valor global determinado não é despesa estimativa.", "5) Sequência V, F, V, F → alternativa C."], "calculo": "Não há cálculo.", "correta": "C) V, F, V, F.", "erradas": ["A) Considera a primeira ou a terceira falsa, contrariando a sequência.", "B) Trata a liquidação como posterior ao pagamento.", "D) Considera correta a utilização de empenho estimativo para valor previamente determinado."], "fundamento": "Lei nº 4.320/1964, arts. 58, 62 e 63.", "pegadinha": "A ordem é EMPENHO → LIQUIDAÇÃO → PAGAMENTO. A liquidação nunca vem depois do pagamento."}$qq$::jsonb, $qq$Sobre os estágios da execução da despesa orçamentária, julgue verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência CORRETA. (__) O empenho é o ato que cria para o ente público a obrigação de pagamento, representando a reserva da dotação orçamentária para determinada despesa. (__) A liquidação da despesa ocorre após o …$qq$),
($qq$3598446$qq$, 181, $qq$AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública$qq$, $qq$FAFIPA - Cont (Pref Franc Beltrão)/Pref Franc Beltrão/2025$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Considerando os estágios da execução da despesa pública previstos na Lei nº 4.320/1964 - empenho, em liquidação, liquidação e pagamento - avalie as situações a seguir, relacionadas à execução orçamentária do exercício de 2024 em uma Prefeitura Municipal. I. Em 05 de abril, foi emitida a nota de empenho no valor de R$ 12.000,00 para aquisição de materiais de expediente. Até o final do mês, não houve entrega nem nota fiscal. ​II. Em 10 de maio, foram entregues uniformes escolares no valor de R$ 18.500,00. O empenho já havia sido feito, mas o pagamento ainda estava em trâmite. A entrega foi atestada e a nota fiscal conferida. III. Em 20 de junho, a equipe técnica confirmou a realização de serviços de dedetização nas escolas municipais. Os serviços foram prestados conforme contrato, e os documentos comprobatórios foram recebidos e atestados. IV. Em 30 de junho, foi registrada a quitação bancária de R$ 15.200,00 referente à contratação de serviços gráficos que já haviam sido empenhados e liquidados anteriormente.  w w .tecconcursos.com.br/questoes/cadernos/104051566/imprimir                                                                                              8/57 Com base nas informações apresentadas e nas normas de execução da despesa pública, é CORRETO afirmar que:$qq$, $qq$[["A", "o item II está na fase de pagamento, pois houve entrega dos uniformes."], ["B", "o item IV encontra-se em liquidação, pois houve o pagamento."], ["C", "o item I encontra-se na fase de liquidação da despesa, pois o empenho já foi realizado."], ["D", "o item III está na fase de liquidação, pois houve comprovação do serviço prestado com documentos hábeis."]]$qq$::jsonb, $qq$D$qq$, 2025, 230, 1097, $qq$A$qq$, $qq${"cobranca": "Estágios da despesa pública", "regra": "A sequência ordinária é empenho → liquidação → pagamento. A liquidação verifica o direito adquirido pelo credor com base nos títulos e documentos comprobatórios e na entrega/prestação efetivamente realizada.", "passos": ["1) Item I: houve apenas empenho; sem entrega ou comprovação, ainda não há liquidação.", "2) Item II: a entrega foi atestada e a nota fiscal conferida, caracterizando a liquidação; o pagamento ainda não ocorreu.", "3) Item III: o serviço foi prestado e comprovado, com documentação atestada; isso caracteriza liquidação.", "4) Item IV: a quitação bancária representa pagamento, posterior ao empenho e à liquidação.", "5) Logo, a afirmativa correta é a III: alternativa D."], "calculo": "Não há cálculo.", "correta": "D) O item III está na fase de liquidação.", "erradas": ["A) Entrega não significa pagamento; o pagamento é a etapa posterior à liquidação.", "B) Pagamento não caracteriza “em liquidação”; é a etapa final da execução da despesa.", "C) Empenho, isoladamente, não equivale à liquidação."], "fundamento": "Lei nº 4.320/1964, arts. 58, 62 e 63.", "pegadinha": "A FAFIPA pode misturar “entrega”, “liquidação” e “pagamento”. A entrega/prestação comprovada permite a liquidação; o pagamento vem depois."}$qq$::jsonb, $qq$Considerando os estágios da execução da despesa pública previstos na Lei nº 4.320/1964 - empenho, em liquidação, liquidação e pagamento - avalie as situações a seguir, relacionadas à execução orçamentária do exercício de 2024 em uma Prefeitura Municipal. I. Em 05 de abril, foi emitida a nota de empenho no valor de R$ 12.000,00 para aquisição de materiais de …$qq$),
($qq$3930706$qq$, 182, $qq$AFO, Direito Financeiro e Contabilidade Pública - Estágios da Despesa Pública$qq$, $qq$FAFIPA - Cont (Pref C Largo)/Pref Campo Largo/2025$qq$, $qq$Caderno Contabilidade P?blica Parte 2$qq$, $qq$Avalie as despesas apresentadas a seguir. Despesa 1: pagamento mensal de R$ 10.000,00 referente ao contrato de aluguel de um imóvel destinado à Secretaria Municipal de Saúde, com valor contratual anual fixo de R$ 120.000,00. Despesa 2: aquisição de 50 cadeiras para o auditório da Prefeitura Municipal, no valor total de R$ 25.000,00, a ser pago integralmente na entrega do material. Despesa 3: pagamento de contas de consumo de energia elétrica das repartições públicas, cujos valores variam de acordo com a utilização mensal. Com base na legislação vigente e nas boas práticas contábeis do setor público, assinale a alternativa que indica CORRETAMENTE os tipos de empenho para cada despesas.$qq$, $qq$[["A", "Despesa 1: Empenho Estimativo; Despesa 2: Empenho Ordinário; Despesa 3: Empenho Global."], ["B", "Despesa 1: Empenho Ordinário; Despesa 2: Empenho Global; Despesa 3: Empenho Estimativo."], ["C", "Despesa 1: Empenho Ordinário; Despesa 2: Empenho Estimativo; Despesa 3: Empenho Global."], ["D", "Despesa 1: Empenho Global; Despesa 2: Empenho Estimativo; Despesa 3: Empenho Ordinário."], ["E", "Despesa 1: Empenho Global; Despesa 2: Empenho Ordinário; Despesa 3: Empenho Estimativo."]]$qq$::jsonb, $qq$E$qq$, 2025, 231, 1097, $qq$A$qq$, $qq${"cobranca": "Tipos de empenho", "regra": "Empenho ordinário é usado para despesa de valor determinado e pagamento único; global, para despesas contratuais sujeitas a parcelamento; estimativo, quando o valor não pode ser previamente determinado.", "passos": ["1) Despesa 1: aluguel anual de R$ 120.000,00, com valor contratual fixo e pagamentos mensais → empenho global.", "2) Despesa 2: 50 cadeiras por R$ 25.000,00, pagamento integral na entrega → empenho ordinário.", "3) Despesa 3: energia elétrica varia conforme o consumo mensal → empenho estimativo.", "4) Sequência global, ordinário, estimativo → alternativa E."], "calculo": "Não há cálculo; a classificação decorre da natureza e da previsibilidade do valor/pagamento.", "correta": "E) Despesa 1: Global; Despesa 2: Ordinário; Despesa 3: Estimativo.", "erradas": ["A) Inverte global/estimativo para despesas que têm valor fixo ou variável.", "B) Trata uma aquisição de pagamento único como empenho global.", "C) Classifica a energia, de valor variável, como global.", "D) Classifica a compra de valor determinado como estimativa."], "fundamento": "Lei nº 4.320/1964, art. 60, §§ 2º e 3º.", "pegadinha": "Valor fixo com pagamentos parcelados aponta para global; valor certo e pagamento único, ordinário; valor não determinável, estimativo."}$qq$::jsonb, $qq$Avalie as despesas apresentadas a seguir. Despesa 1: pagamento mensal de R$ 10.000,00 referente ao contrato de aluguel de um imóvel destinado à Secretaria Municipal de Saúde, com valor contratual anual fixo de R$ 120.000,00. Despesa 2: aquisição de 50 cadeiras para o auditório da Prefeitura Municipal, no valor total de R$ 25.000,00, a ser pago integralmente …$qq$),
($qq$2746467$qq$, 183, $qq$Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)$qq$, $qq$FAFIPA - Cont (CM A Chateaubriand)/CM A Chateaubriand/2023$qq$, $qq$Caderno Contabilidade Geral Parte 1$qq$, $qq$De acordo com a NBC TG Estrutura Conceitual, atribua (V) para verdadeiro e (F) para falso no que se afirma e, em seguida, assinale a alternativa com a sequência CORRETA: () A mensuração custo corrente não fornece informações monetárias sobre ativos, passivos e respectivas receitas e despesas, utilizando informações derivadas, pelo menos em parte, do preço da transação ou outro evento que deu origem a eles. Este método de mensuração não reflete as mudanças nos valores, exceto na medida em que essas mudanças se referirem à redução ao valor recuperável de ativo ou passivo que se torna onerosa. () Valor justo é o preço que seria recebido pela venda de ativo ou que seria pago pela transferência de passivo em transação ordenada entre participantes do mercado na data de mensuração. () Valor em uso é o valor presente dos fluxos de caixa, ou outros benefícios econômicos, que a entidade espera obter do uso de ativo e de sua alienação final. () Valor de cumprimento é o valor presente do caixa, ou de outros recursos econômicos, que a entidade espera ser obrigada a transferir para cumprir a obrigação. () O custo histórico de ativo é o custo de ativo equivalente na data de mensuração, compreendendo a contraprestação que seria paga na data de mensuração mais os custos de transação que seriam incorridos nessa data. Assinale a alternativa que contem a sequência CORRETA.$qq$, $qq$[["A", "F; V; V; V; F."], ["B", "F; V; F; F; F."], ["C", "V; F; F; F; V."], ["D", "V; V; F; V; F."]]$qq$::jsonb, $qq$A$qq$, 2023, 28, 1096, $qq$A$qq$, $qq${"cobranca": "Bases de mensuração – CPC 00", "regra": "Custo corrente usa informações atuais de preço/custo; valor justo é preço de saída em transação ordenada; valor em uso é valor presente dos benefícios esperados do uso e alienação; valor de cumprimento é o valor presente dos recursos a transferir para cumprir obrigação; custo histórico parte dos custos da aquisição/criação.", "passos": ["1) Primeira afirmação: Falsa. A descrição apresentada não corresponde ao custo corrente; ela descreve características de mensuração baseadas no evento original.", "2) Segunda: Verdadeira. É a definição de valor justo.", "3) Terceira: Verdadeira. É a definição de valor em uso.", "4) Quarta: Verdadeira. É a definição de valor de cumprimento.", "5) Quinta: Falsa. A descrição é de custo corrente, não de custo histórico.", "6) Sequência F-V-V-V-F → alternativa A."], "calculo": "Não há cálculo.", "correta": "A) F; V; V; V; F.", "erradas": ["B) Torna falsas as afirmações III e IV, que estão de acordo com as definições.", "C) Inverte a classificação das duas primeiras afirmações.", "D) Considera verdadeira a descrição do custo corrente como custo histórico."], "fundamento": "NBC TG Estrutura Conceitual – bases de mensuração.", "pegadinha": "Diferencie custo histórico de custo corrente: histórico olha para os custos da aquisição/criação; corrente considera o custo de um ativo equivalente na data da mensuração."}$qq$::jsonb, $qq$De acordo com a NBC TG Estrutura Conceitual, atribua (V) para verdadeiro e (F) para falso no que se afirma e, em seguida, assinale a alternativa com a sequência CORRETA: () A mensuração custo corrente não fornece informações monetárias sobre ativos, passivos e respectivas receitas e despesas, utilizando informações derivadas, pelo menos em parte, do preço da…$qq$),
($qq$2746469$qq$, 184, $qq$Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)$qq$, $qq$FAFIPA - Cont (CM A Chateaubriand)/CM A Chateaubriand/2023$qq$, $qq$Caderno Contabilidade Geral Parte 1$qq$, $qq$Sobre as características qualitativas de informações financeiras úteis, previstas na NBC TG Estrutura Conceitual, considere as afirmativas a seguir: I. Classificar, caracterizar e apresentar informações de modo claro e conciso as torna compreensíveis. II. Relatórios financeiros representam fenômenos econômicos em palavras e números. Para serem úteis, informações financeiras não devem apenas representar fenômenos relevantes, mas também representar de forma fidedigna a essência dos fenômenos que pretendem representar. III. Informações sobre a entidade que reporta são mais úteis se puderem ser comparadas à informações similares sobre outras entidades e à informações similares sobre a mesma entidade referentes a outro período ou a outra data. IV. Informações financeiras relevantes são capazes de fazer diferença nas decisões tomadas pelos usuários. V. Capacidade de verificação significa que diferentes observadores bem informados e independentes podem chegar ao consenso, embora não a acordo necessariamente completo, de que a representação específica é representação fidedigna. VI. Tempestividade significa disponibilizar informações aos tomadores de decisões a tempo para que sejam capazes de influenciar suas decisões. Sobre as características qualitativas de informações financeiras úteis, assinale a alternativa CORRETA.$qq$, $qq$[["A", "As características qualitativas de melhoria são comparabilidade, capacidade de verificação, tempestividade e compreensibilidade."], ["B", "As características qualitativas de melhoria são relevância e representação fidedigna."], ["C", "As características qualitativas fundamentais são comparabilidade, capacidade de verificação, tempestividade e compreensibilidade."], ["D", "As características qualitativas fundamentais são comparabilidade e tempestividade."]]$qq$::jsonb, $qq$A$qq$, 2023, 29, 1096, $qq$A$qq$, $qq${"cobranca": "Características qualitativas da informação financeira", "regra": "As características fundamentais são relevância e representação fidedigna. As características de melhoria são comparabilidade, capacidade de verificação, tempestividade e compreensibilidade.", "passos": ["1) I descreve compreensibilidade: verdadeiro.", "2) II descreve representação fidedigna: verdadeiro.", "3) III descreve comparabilidade: verdadeiro.", "4) IV descreve relevância: verdadeiro.", "5) V descreve capacidade de verificação: verdadeiro.", "6) VI descreve tempestividade: verdadeiro.", "7) Portanto, a alternativa que identifica corretamente as características de melhoria é A."], "calculo": "Não há cálculo.", "correta": "A) Comparabilidade, capacidade de verificação, tempestividade e compreensibilidade.", "erradas": ["B) Relevância e representação fidedigna são características fundamentais, não de melhoria.", "C) Lista as características de melhoria como se fossem fundamentais.", "D) Novamente classifica características de melhoria como fundamentais."], "fundamento": "NBC TG Estrutura Conceitual – características qualitativas fundamentais e de melhoria.", "pegadinha": "Memorize a divisão: FUNDAMENTAIS = relevância + representação fidedigna; MELHORIA = comparabilidade + verificabilidade + tempestividade + compreensibilidade."}$qq$::jsonb, $qq$Sobre as características qualitativas de informações financeiras úteis, previstas na NBC TG Estrutura Conceitual, considere as afirmativas a seguir: I. Classificar, caracterizar e apresentar informações de modo claro e conciso as torna compreensíveis. II. Relatórios financeiros representam fenômenos econômicos em palavras e números. Para serem úteis, informa…$qq$),
($qq$3998517$qq$, 185, $qq$Contabilidade Geral - Estrutura Conceitual Básica da Contabilidade (CPC 00)$qq$, $qq$FAFIPA - Cont (CM Terra Roxa)/CM Terra Roxa/2023$qq$, $qq$Caderno Contabilidade Geral Parte 1$qq$, $qq$Conforme dispõe a NBC TG Estrutura Conceitual, o reconhecimento de despesa ocorre ao mesmo tempo que: I.O reconhecimento inicial do ativo, ou aumento no valor contábil do ativo. II.O reconhecimento inicial do passivo, ou aumento no valor contábil do passivo. III.O desreconhecimento do ativo, ou diminuição no valor contábil do ativo. IV.O desreconhecimento do passivo, ou diminuição no valor contábil do passivo. Está CORRETO o que se afirma em:$qq$, $qq$[["A", "II e III, apenas."], ["B", "I, II, III e IV."], ["C", "I e IV, apenas."], ["D", "I e II, apenas."], ["E", "II e IV, apenas."]]$qq$::jsonb, $qq$A$qq$, 2023, 30, 1096, $qq$A$qq$, $qq${"cobranca": "Reconhecimento de despesas – CPC 00", "regra": "A despesa é reconhecida quando ocorre diminuição de ativos ou aumento de passivos que resulta em diminuição do patrimônio líquido, exceto distribuições aos proprietários. O reconhecimento ocorre, em particular, com reconhecimento/aumento de passivo ou desreconhecimento/diminuição de ativo.", "passos": ["1) I: não é regra geral. Reconhecimento inicial ou aumento de ativo normalmente se relaciona a reconhecimento de ativo, não de despesa.", "2) II: verdadeiro; o reconhecimento inicial/aumento de passivo pode resultar no reconhecimento de despesa.", "3) III: verdadeiro; desreconhecimento/diminuição de ativo pode resultar em despesa.", "4) IV: não é a regra geral indicada; diminuição de passivo pode representar aumento de patrimônio líquido/receita, e não despesa.", "5) Logo, II e III apenas → alternativa A."], "calculo": "Não há cálculo.", "correta": "A) II e III, apenas.", "erradas": ["B) Inclui I e IV, que não correspondem à regra geral de reconhecimento de despesa.", "C) Considera I e IV corretas.", "D) Considera I correta e exclui III.", "E) Inclui IV e exclui III."], "fundamento": "NBC TG Estrutura Conceitual – reconhecimento de receitas e despesas e definição de despesa.", "pegadinha": "Não confunda toda variação patrimonial com despesa: aumento de ativo pode representar receita/contrapartida, e redução de passivo pode representar receita."}$qq$::jsonb, $qq$Conforme dispõe a NBC TG Estrutura Conceitual, o reconhecimento de despesa ocorre ao mesmo tempo que: I.O reconhecimento inicial do ativo, ou aumento no valor contábil do ativo. II.O reconhecimento inicial do passivo, ou aumento no valor contábil do passivo. III.O desreconhecimento do ativo, ou diminuição no valor contábil do ativo. IV.O desreconhecimento do…$qq$),
($qq$2416285$qq$, 186, $qq$AFO, Direito Financeiro e Contabilidade Pública - Classificação da Despesa Orçamentária$qq$, $qq$FAFIPA - Cont (FAZPREV)/FAZPREV/2023$qq$, $qq$Caderno Contabilidade P?blica Parte 1$qq$, $qq$A dívida surge e aumenta sempre que o governo gasta mais do que arrecada. Assim, quando os impostos e demais receitas não são suficientes para cobrir as despesas, o governo é financiado por seus credores (pessoas físicas, empresas, bancos etc), dando origem à dívida pública. Segundo a Lei 4.320/64, as dotações para amortização da dívida pública serão classificadas como:$qq$, $qq$[["A", "Transferência de Capital."], ["B", "Inversões financeiras."], ["C", "Investimentos."], ["D", "Transferências correntes."], ["E", "Despesas de Custeio."]]$qq$::jsonb, $qq$A$qq$, 2023, 86, 1096, $qq$A$qq$, $qq${"cobranca": "Classificação da despesa – amortização da dívida", "regra": "Na classificação econômica da Lei nº 4.320/1964, a amortização da dívida pública integra as transferências de capital no agrupamento tradicional da lei.", "passos": ["1) A questão pede a classificação prevista na Lei nº 4.320/1964.", "2) Amortização da dívida pública não é investimento nem inversão financeira.", "3) Na classificação econômica da Lei 4.320, aparece em transferências de capital.", "4) Portanto, a alternativa A corresponde ao gabarito."], "calculo": "Não há cálculo.", "correta": "A) Transferência de Capital.", "erradas": ["B) Inversões financeiras não abrangem a amortização da dívida.", "C) Investimentos correspondem a despesas de capital com obras e aquisições que formam/geram bens de capital.", "D) Transferências correntes são despesas correntes.", "E) Despesas de custeio são correntes."], "fundamento": "Lei nº 4.320/1964, art. 12 e classificação econômica das despesas.", "pegadinha": "A questão usa a classificação tradicional da Lei 4.320/64; não substitua automaticamente a nomenclatura histórica pela classificação por natureza atualmente utilizada no MCASP."}$qq$::jsonb, $qq$