-- Parte 21, passo 3 de 3 — RODAR POR ÚLTIMO. Recoloca 150 das 964 questões de Contabilidade no rank final (intercalado com as novas matérias) e grava as resoluções novas (ranks originais 121-560, batch 541_560.json) que ainda não tinham sido salvas no Supabase.
on conflict (id) do update set
  rank = excluded.rank,
  topic = excluded.topic,
  origin = excluded.origin,
  file_source = excluded.file_source,
  stem = excluded.stem,
  options = excluded.options,
  answer = excluded.answer,
  year = excluded.year,
  qnum = excluded.qnum,
  score = excluded.score,
  band = excluded.band,
  resolution = coalesce(excluded.resolution, public.questoes.resolution),
  summary = excluded.summary;
